{"command":"python3 << 'PY'
import subprocess, struct, os, time, socket

def ssh_str(b):
    if isinstance(b,str): b=b.encode()
    return struct.pack(">I", len(b))+b
def ssh_mpint(n):
    if n==0:
        return struct.pack(">I",0)
    b=n.to_bytes((n.bit_length()+7)//8,'big')
    if b[0]&0x80: b=b'\x00'+b
    return struct.pack(">I", len(b))+b

def run_key(data, name="/tmp/probe_key"):
    open(name,"wb").write(data)
    os.chmod(name,0o600)
    try:
        p=subprocess.Popen(["./executable","-F","-r",name,"-p","2299","-P","/tmp/probe_pid"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        time.sleep(0.6)
        if p.poll() is not None:
            out,err=p.communicate()
            print(" exited rc",p.returncode, repr(err[:600]))
        else:
            print(" RUNNING (loaded ok)")
            # check banner
            try:
                s=socket.socket(); s.settimeout(2); s.connect(("127.0.0.1",2299)); print(" banner", repr(s.recv(200)[:100])); s.close()
            except Exception as e: print(" sock err",e)
            p.terminate()
            try: out,err=p.communicate(timeout=2)
            except: p.kill(); out,err=p.communicate()
            print(" after term", repr(err[:600]))
    except Exception as e:
        print(" exc",e)

print("empty:"); run_key(b"")
print("just type ed25519:"); run_key(ssh_str("ssh-ed25519"))
print("ed with pub+priv zero:")
pub=b"\x00"*32; priv=b"\x00"*64
run_key(ssh_str("ssh-ed25519")+ssh_str(pub)+ssh_str(priv))
print("ed pub 32 priv 32:")
run_key(ssh_str("ssh-ed25519")+ssh_str(pub)+ssh_str(b"\x00"*32))
print("ssh-rsa empty:"); run_key(ssh_str("ssh-rsa"))
print("unknown type:"); run_key(ssh_str("foobar"))
print("dss:"); run_key(ssh_str("ssh-dss"))
PY
