# generate ed25519 using openssl via subprocess parsing DER
import subprocess, struct, os, time, socket

def ssh_str(b):
    if isinstance(b,str): b=b.encode()
    return struct.pack(">I", len(b))+b

# openssl key
subprocess.run(["openssl","genpkey","-algorithm","ED25519","-out","/tmp/ed_openssl.pem"], check=True)
# dump DER
der=subprocess.check_output(["openssl","pkey","-in","/tmp/ed_openssl.pem","-outform","DER"])
print("DER len",len(der),der.hex())
# DER private: last 34 bytes usually 0420 + 32 seed ; public in DER pubkey
pubder=subprocess.check_output(["openssl","pkey","-in","/tmp/ed_openssl.pem","-pubout","-outform","DER"])
print("PUBDER",pubder.hex())
seed=der[-32:]
pub=pubder[-32:]
print("seed",seed.hex(),"pub",pub.hex())

def run_key(data, label):
    open("/tmp/probe_key","wb").write(data); os.chmod("/tmp/probe_key",0o600)
    p=subprocess.Popen(["./executable","-F","-r","/tmp/probe_key","-p","2299","-P","/tmp/probe_pid"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    time.sleep(0.5)
    if p.poll() is not None:
        out,err=p.communicate(); print(label,"exited",p.returncode,repr(err[:400]))
    else:
        print(label,"RUNNING OK")
        try:
            s=socket.socket(); s.settimeout(2); s.connect(("127.0.0.1",2299)); print(" banner",repr(s.recv(500)[:400])); s.close()
        except Exception as e: print(" sock",e)
        p.terminate()
        try: out,err=p.communicate(timeout=2)
        except: p.kill(); out,err=p.communicate()
        print(" term log",repr(err[:400]))

variants={
 "pub,priv64(seed+pub)": ssh_str("ssh-ed25519")+ssh_str(pub)+ssh_str(seed+pub),
 "pub,priv32seed": ssh_str("ssh-ed25519")+ssh_str(pub)+ssh_str(seed),
 "pub,priv64(pub+seed)": ssh_str("ssh-ed25519")+ssh_str(pub)+ssh_str(pub+seed),
 "priv64,pub swapped": ssh_str("ssh-ed25519")+ssh_str(seed+pub)+ssh_str(pub),
}
for k,v in variants.items(): run_key(v,k)
PY
