import subprocess, struct, os, time, re
def ssh_str(b):
    if isinstance(b,str): b=b.encode()
    return struct.pack(">I", len(b))+b
def ssh_mp(n):
    if n==0: return struct.pack(">I",0)
    b=n.to_bytes((n.bit_length()+7)//8,'big')
    if b[0]&0x80: b=b'\x00'+b
    return struct.pack(">I", len(b))+b
def run_key(data, label):
    open("/tmp/probe_key","wb").write(data); os.chmod("/tmp/probe_key",0o600)
    p=subprocess.Popen(["./executable","-F","-r","/tmp/probe_key","-p","2299","-P","/tmp/probe_pid"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    time.sleep(0.4)
    if p.poll() is not None:
        out,err=p.communicate(); print(label,"EXIT",repr(err[:300])); return False
    else:
        print(label,"RUNNING"); p.terminate()
        try: out,err=p.communicate(timeout=2)
        except: p.kill(); out,err=p.communicate()
        return True

subprocess.run(["openssl","genrsa","-out","/tmp/rsa_openssl.pem","2048"], check=True, capture_output=True)
txt=subprocess.check_output(["openssl","rsa","-in","/tmp/rsa_openssl.pem","-text","-noout"]).decode()
# parse sections
def parse_num(name, txt):
    # name followed by: hex bytes lines or (decimal)
    m=re.search(name+r":\s*(?:\(\d+ bit\))?\s*((?:\s*[0-9a-f]{2}:?[0-9a-f:]*\n?)+)", txt)
    # easier manual
    return None

# Use openssl to output? Alternative parse with simple state machine
lines=txt.splitlines()
data={}
current=None
for line in lines:
    stripped=line.strip()
    # detect label
    m=re.match(r"(modulus|publicExponent|privateExponent|prime1|prime2|exponent1|exponent2|coefficient):(?:\s*\((\d+).*))?(?:\s*(\d+))?", stripped)
    if m and not re.match(r"^[0-9a-f]{2}:", stripped):
        label=m.group(1)
        current=label
        data[current]=[]
        # publicExponent has number
        if label=="publicExponent":
            mm=re.search(r"\((\d+)\)", line)
            # Actually text: publicExponent: 65537 (0x010001)
            mm2=re.search(r":\s*(\d+)",line)
            if mm2: data[current]=[int(mm2.group(1))]
            current=None
        continue
    if re.match(r"^[0-9a-f]{2}(:[0-9a-f]{2})*:?$", stripped):
        if current:
            hexs=stripped.rstrip(":").replace(":","")
            data[current].append(hexs)
    elif stripped.startswith("exponent") or stripped.startswith("coefficient"):
        pass

def get_int(name):
    v=data[name]
    if isinstance(v,list) and v and isinstance(v[0],int): return v[0]
    hexstr="".join(v)
    return int.from_bytes(bytes.fromhex(hexstr),'big')

for k in data: print(k, type(data[k]))
n=get_int("modulus"); e=get_int("publicExponent"); d=get_int("privateExponent"); p=get_int("prime1"); q=get_int("prime2"); dp=get_int("exponent1"); dq=get_int("exponent2"); iqmp=get_int("coefficient")
print("n bits",n.bit_length(),"e",e,"p*q==n",p*q==n, "iqmp*q%p", iqmp*q%p)

cands={
 "e,n,d,p,q,iqmp": [e,n,d,p,q,iqmp],
 "e,n,d,p,q": [e,n,d,p,q],
 "n,e,d,p,q,iqmp": [n,e,d,p,q,iqmp],
 "e,n,d,q,p,iqmp": [e,n,d,q,p,iqmp],
