func parseUint32Strict(s string) (uint32, bool) {
	// emulate strtoul(s, &end, 10) + checks used by dropbear:
	// leading whitespace and sign allowed, must consume all,
	// value (after unsigned long conversion) must fit uint32
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\v' || s[i] == '\f' || s[i] == '\r') {
		i++
	}
	neg := false
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	start := i
	var val uint64
	overflow := false
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		d := uint64(s[i] - '0')
		if !overflow {
			// check > max uint64
			if val > (^uint64(0)-d)/10 {
				overflow = true
			} else {
				val = val*10 + d
			}
		}
		i++
	}
	if start == i || i != len(s) || overflow {
		return 0, false
	}
	if neg {
		val = -val // two's complement in uint64
	}
	if val > 0xffffffff {
		return 0, false
	}
	return uint32(val), true
}

func strerrorName(err error) string {
	// map common Go errors to C strerror strings
	if err == nil {
		return ""
	}
	msg := err.Error()
	type syscallErr interface{ Errno() uintptr }
	// try to extract errno text via known substrings
	lower := strings.ToLower(msg)
	switch {
	case strings.Contains(lower, "address already in use"):
		return "Address already in use"
	case strings.Contains(lower, "connection refused"):
		return "Connection refused"
	case strings.Contains(lower, "connection reset by peer"):
		return "Connection reset by peer"
	case strings.Contains(lower, "broken pipe"):
		return "Broken pipe"
	case strings.Contains(lower, "permission denied"):
		return "Permission denied"
	case strings.Contains(lower, "no such file or directory"):
		return "No such file or directory"
	case strings.Contains(lower, "file exists"):
		return "File exists"
	case strings.Contains(lower, "cannot assign requested address"):
		return "Cannot assign requested address"
	case strings.Contains(lower, "network is unreachable"):
		return "Network is unreachable"
	case strings.Contains(lower, "host is down"):
		return "Host is down"
	case strings.Contains(lower, "no route to host"):
		return "No route to host"
	case strings.Contains(lower, "operation not permitted"):
		return "Operation not permitted"
	case strings.Contains(lower, "invalid argument"):
		return "Invalid argument"
	case strings.Contains(lower, "socket operation on non-socket"):
		return "Socket operation on non-socket"
	case strings.Contains(lower, "resource temporarily unavailable"):
		return "Resource temporarily unavailable"
	case strings.Contains(lower, "interrupted system call"):
		return "Interrupted system call"
	case strings.Contains(lower, "input/output error"):
		return "Input/output error"
	case strings.Contains(lower, "no such device"):
		return "No such device or address"
	}
	// strip go prefixes up to last ": "
	if idx := strings.LastIndex(msg, ": "); idx >= 0 {
		return msg[idx+2:]
	}
	return msg
}

func quoteListContains(list string, item string) bool {
	if list == "" {
		return false
	}
	for _, p := range strings.Split(list, ",") {
		if p == item {
			return true
		}
	}
	return false
}

// choose first entry in client list that appears in server list, skipping pseudo entries
func negotiate(clientList string, serverList string) (string, bool) {
	if clientList == "" {
		return "", false
	}
	server := make(map[string]bool)
	for _, p := range strings.Split(serverList, ",") {
		server[p] = true
	}
	for _, p := range strings.Split(clientList, ",") {
		if server[p] {
			return p, true
		}
	}
	return "", false
}
