// ----- parsing dropbear key files -----

type keyParseError struct {
	kind string // "failed", "String too long", "Bad buf_getptr"
}

func (e *keyParseError) Error() string { return e.kind }

type fileReader struct {
	data []byte
	pos  int
}

func (fr *fileReader) getString() ([]byte, *keyParseError) {
	if fr.pos+4 > len(fr.data) {
		return nil, &keyParseError{"Bad buf_getptr"}
	}
	l := int(uint32(fr.data[fr.pos])<<24 | uint32(fr.data[fr.pos+1])<<16 | uint32(fr.data[fr.pos+2])<<8 | uint32(fr.data[fr.pos+3]))
	fr.pos += 4
	if l < 0 || l > len(fr.data)-fr.pos {
		return nil, &keyParseError{"String too long"}
	}
	b := make([]byte, l)
	copy(b, fr.data[fr.pos:fr.pos+l])
	fr.pos += l
	return b, nil
}
func (fr *fileReader) getMpint() (*big.Int, *keyParseError) {
	b, err := fr.getString()
	if err != nil {
		return nil, err
	}
	if len(b) == 0 {
		return big.NewInt(0), nil
	}
	if b[0]&0x80 != 0 {
		v := new(big.Int).SetBytes(b)
		neg := new(big.Int).Lsh(big.NewInt(1), uint(len(b)*8))
		v.Sub(v, neg)
		return v, nil
	}
	return new(big.Int).SetBytes(b), nil
}

var ecdsaCurves = map[string]struct {
	algo string
	curve elliptic.Curve
	size int
	qsize int
}{
	"nistp256": {"ecdsa-sha2-nistp256", elliptic.P256(), 256, 65},
	"nistp384": {"ecdsa-sha2-nistp384", elliptic.P384(), 384, 97},
	"nistp521": {"ecdsa-sha2-nistp521", elliptic.P521(), 521, 133},
}

func parseDropbearKey(data []byte) (*HostKey, error) {
	if len(data) == 0 {
		return nil, &keyParseError{"Bad buf_getptr"}
	}
	fr := &fileReader{data: data}
	typeBytes, kerr := fr.getString()
	if kerr != nil {
		return nil, kerr
	}
	typ := string(typeBytes)
	hk := &HostKey{Type: typ}
	switch typ {
	case "ssh-ed25519":
		priv, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		pub, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		if len(priv) != 64 || len(pub) != 32 {
			return nil, &keyParseError{"failed"}
		}
		// validate pub matches seed
		derived := ed25519.NewKeyFromSeed(priv[:32])
		if string(derived[32:]) != string(pub) || string(priv[32:]) != string(pub) {
			return nil, &keyParseError{"failed"}
		}
		hk.EdPriv = ed25519.PrivateKey(append([]byte{}, priv...))
		hk.EdPub = ed25519.PublicKey(append([]byte{}, pub...))
		return hk, nil
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		curveBytes, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		info, ok := ecdsaCurves[string(curveBytes)]
		if !ok || info.algo != typ {
			return nil, &keyParseError{"failed"}
		}
		q, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		d, kerr := fr.getMpint()
		if kerr != nil {
			return nil, kerr
		}
		if len(q) != info.qsize {
			return nil, &keyParseError{"failed"}
		}
		x, y := elliptic.Unmarshal(info.curve, q)
		if x == nil || !info.curve.IsOnCurve(x, y) {
			return nil, &keyParseError{"failed"}
		}
		if d.Sign() <= 0 {
			return nil, &keyParseError{"failed"}
		}
		// check d corresponds to Q
		gx, gy := info.curve.ScalarBaseMult(padBytes(d.Bytes(), (info.size+7)/8))
		if gx == nil || gx.Cmp(x) != 0 || gy.Cmp(y) != 0 {
			return nil, &keyParseError{"failed"}
		}
		hk.ECDSACurve = string(curveBytes)
		hk.ECDSAQ = append([]byte{}, q...)
		hk.ECDSAD = d
		hk.ecCurve = info.curve
		return hk, nil
	case "ssh-rsa":
		var vals []*big.Int
		for i := 0; i < 6; i++ {
			v, kerr := fr.getMpint()
			if kerr != nil {
				if kerr.kind == "Bad buf_getptr" && i >= 5 {
					break
				}
				if kerr.kind == "Bad buf_getptr" && i == 5 {
					break
				}
				// missing iqmp tolerated?
				if i == 5 {
					break
				}
				return nil, kerr
			}
			vals = append(vals, v)
		}
		if len(vals) < 5 {
			return nil, &keyParseError{"failed"}
		}
		hk.RSAE, hk.RSAN, hk.RSAD, hk.RSAP, hk.RSAQ = vals[0], vals[1], vals[2], vals[3], vals[4]
		if len(vals) >= 6 {
			hk.RSAIQ = vals[5]
		}
		if hk.RSAN.BitLen() < 1024 {
			logMsg("RSA key too short")
			return nil, &keyParseError{"failed"}
		}
		// consistency: p*q==n
		prod := new(big.Int).Mul(hk.RSAP, hk.RSAQ)
		if prod.Cmp(hk.RSAN) != 0 {
			return nil, &keyParseError{"failed"}
		}
		if hk.RSAE.Sign() <= 0 || hk.RSAD.Sign() <= 0 {
			return nil, &keyParseError{"failed"}
		}
		return hk, nil
	default:
		return nil, &keyParseError{"failed"}
	}
}

func padBytes(b []byte, size int) []byte {
	if len(b) >= size {
		return b
	}
	out := make([]byte, size)
	copy(out[size-len(b):], b)
	return out
}

func writeDropbearKey(hk *HostKey) []byte {
	w := &writer{}
	switch hk.Type {
	case "ssh-ed25519":
		w.str("ssh-ed25519")
		w.strBytes(hk.EdPriv)
		w.strBytes(hk.EdPub)
	case "ssh-rsa":
		w.str("ssh-rsa")
		w.mpint(hk.RSAE)
		w.mpint(hk.RSAN)
		w.mpint(hk.RSAD)
		w.mpint(hk.RSAP)
		w.mpint(hk.RSAQ)
		if hk.RSAIQ != nil {
			w.mpint(hk.RSAIQ)
		}
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		w.str(hk.Type)
		w.str(hk.ECDSACurve)
		w.strBytes(hk.ECDSAQ)
		w.mpint(hk.ECDSAD)
	}
