func keyTypeDisplay(hk *HostKey) string {
	switch hk.Type {
	case "ssh-rsa":
		return "RSA"
	case "ssh-ed25519":
		return "ed25519"
	case "ecdsa-sha2-nistp256":
		return "ECDSA256"
	case "ecdsa-sha2-nistp384":
		return "ECDSA384"
	case "ecdsa-sha2-nistp521":
		return "ECDSA521"
	}
	return hk.Type
}

func generateHostKey(algo string) (*HostKey, error) {
	switch algo {
	case "ssh-ed25519":
		pub, priv, err := ed25519.GenerateKey(randReader{})
		if err != nil {
			return nil, err
		}
		return &HostKey{Type: "ssh-ed25519", EdPriv: priv, EdPub: pub}, nil
	case "rsa-sha2-256", "ssh-rsa":
		return generateRSA()
	case "ecdsa-sha2-nistp256":
		return generateECDSA("nistp256")
	case "ecdsa-sha2-nistp384":
		return generateECDSA("nistp384")
	case "ecdsa-sha2-nistp521":
		return generateECDSA("nistp521")
	}
	return nil, fmt.Errorf("unknown key type %s", algo)
}

type randReader struct{}

func (randReader) Read(p []byte) (int, error) {
	// use crypto/rand via a helper to avoid import cycle inside expressions
	return readRand(p)
}

func generateRSA() (*HostKey, error) {
	// use crypto/rsa
	key, err := rsaGenerateKey(2048)
	if err != nil {
		return nil, err
	}
	p := key.Primes[0]
	q := key.Primes[1]
	iq := new(big.Int).ModInverse(q, p)
	return &HostKey{
		Type: "ssh-rsa",
		RSAE: big.NewInt(int64(key.PublicKey.E)),
		RSAN: key.PublicKey.N,
		RSAD: key.D,
		RSAP: p,
		RSAQ: q,
		RSAIQ: iq,
	}, nil
}

func generateECDSA(curveName string) (*HostKey, error) {
	info := ecdsaCurves[curveName]
	priv, err := ecdsaGenerateKey(info.curve)
	if err != nil {
		return nil, err
	}
	q := elliptic.Marshal(info.curve, priv.PublicKey.X, priv.PublicKey.Y)
	return &HostKey{
		Type: info.algo,
		ECDSACurve: curveName,
		ECDSAQ: q,
		ECDSAD: priv.D,
		ecCurve: info.curve,
	}, nil
}

// ensure a hostkey for the given negotiated algorithm exists (loading/generating delayed)
// returns key or error reason string
func (sess *session) ensureHostKey(algo string) *HostKey {
	// loaded entries first
	for _, e := range sess.opts.Entries {
		if !e.Loaded {
			continue
		}
		hk, err := parseDropbearKey(e.Data)
		if err != nil {
			continue
		}
		if hk.algoName() == algo {
			return hk
		}
	}
	// delayed entries
	for _, e := range sess.opts.Entries {
		if !e.Delayed {
			continue
		}
		if e.DelayType == "" {
			continue
		}
		// match by algo name: delayed types stored as algo names already
		if delayedAlgoName(e.DelayType) != algo {
			continue
		}
		// try load file if exists
		if data, err := os.ReadFile(e.Path); err == nil {
			hk, err := parseDropbearKey(data)
			if err == nil && hk.algoName() == algo {
				return hk
			}
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		// generate
		hk, err := generateHostKey(algo)
		if err != nil {
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		tmpPath := fmt.Sprintf("%s.tmp%d", e.Path, os.Getpid())
		f, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
		if err != nil {
			logMsg("Couldn't create new file %s: %s", tmpPath, strerrorName(err))
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		_, werr := f.Write(writeDropbearKey(hk))
