		prefix = []byte{0x30, 0x31, 0x30, 0x0d, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01, 0x05, 0x00, 0x04, 0x20}
	case crypto.SHA512:
		prefix = []byte{0x30, 0x51, 0x30, 0x0d, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x03, 0x05, 0x00, 0x04, 0x40}
	case crypto.SHA1:
		prefix = []byte{0x30, 0x21, 0x30, 0x09, 0x06, 0x05, 0x2b, 0x0e, 0x03, 0x02, 0x1a, 0x05, 0x00, 0x04, 0x10}
	default:
		return nil, errors.New("bad hash")
	}
	k := (hk.RSAN.BitLen() + 7) / 8
	t := append(append([]byte{}, prefix...), digest...)
	if k < len(t)+11 {
		return nil, errors.New("key too small")
	}
	em := make([]byte, k)
	em[0] = 0x00
	em[1] = 0x01
	ps := k - len(t) - 3
	for i := 0; i < ps; i++ {
		em[2+i] = 0xff
	}
	em[2+ps] = 0x00
	copy(em[3+ps:], t)
	m := new(big.Int).SetBytes(em)
	s := new(big.Int).Exp(m, hk.RSAD, hk.RSAN)
	sb := s.Bytes()
	out := make([]byte, k)
	copy(out[k-len(sb):], sb)
	return out, nil
}

// ----- parsing dropbear key files -----

type keyParseError struct {
	kind string // "failed", "String too long", "Bad buf_getptr"
}

func (e *keyParseError) Error() string { return e.kind }

type fileReader struct {
	data []byte
	pos  int
}

func (fr *fileReader) getString() ([]byte, *keyParseError) {
	if fr.pos+4 > len(fr.data) {
		return nil, &keyParseError{"Bad buf_getptr"}
	}
	l := int(uint32(fr.data[fr.pos])<<24 | uint32(fr.data[fr.pos+1])<<16 | uint32(fr.data[fr.pos+2])<<8 | uint32(fr.data[fr.pos+3]))
	fr.pos += 4
	if l < 0 || l > len(fr.data)-fr.pos {
		return nil, &keyParseError{"String too long"}
	}
	b := make([]byte, l)
	copy(b, fr.data[fr.pos:fr.pos+l])
	fr.pos += l
	return b, nil
}
func (fr *fileReader) getMpint() (*big.Int, *keyParseError) {
	b, err := fr.getString()
	if err != nil {
		return nil, err
	}
	if len(b) == 0 {
		return big.NewInt(0), nil
	}
	if b[0]&0x80 != 0 {
		v := new(big.Int).SetBytes(b)
		neg := new(big.Int).Lsh(big.NewInt(1), uint(len(b)*8))
		v.Sub(v, neg)
		return v, nil
	}
	return new(big.Int).SetBytes(b), nil
}

var ecdsaCurves = map[string]struct {
	algo string
	curve elliptic.Curve
	size int
	qsize int
}{
	"nistp256": {"ecdsa-sha2-nistp256", elliptic.P256(), 256, 65},
	"nistp384": {"ecdsa-sha2-nistp384", elliptic.P384(), 384, 97},
	"nistp521": {"ecdsa-sha2-nistp521", elliptic.P521(), 521, 133},
}

func parseDropbearKey(data []byte) (*HostKey, error) {
	if len(data) == 0 {
		return nil, &keyParseError{"Bad buf_getptr"}
	}
	fr := &fileReader{data: data}
	typeBytes, kerr := fr.getString()
	if kerr != nil {
		return nil, kerr
	}
	typ := string(typeBytes)
	hk := &HostKey{Type: typ}
	switch typ {
	case "ssh-ed25519":
		priv, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		pub, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		if len(priv) != 64 || len(pub) != 32 {
			return nil, &keyParseError{"failed"}
		}
		// validate pub matches seed
		derived := ed25519.NewKeyFromSeed(priv[:32])
		if string(derived[32:]) != string(pub) || string(priv[32:]) != string(pub) {
			return nil, &keyParseError{"failed"}
		}
		hk.EdPriv = ed25519.PrivateKey(append([]byte{}, priv...))
		hk.EdPub = ed25519.PublicKey(append([]byte{}, pub...))
		return hk, nil
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		curveBytes, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		info, ok := ecdsaCurves[string(curveBytes)]
		if !ok || info.algo != typ {
			return nil, &keyParseError{"failed"}
		}
		q, kerr := fr.getString()
		if kerr != nil {
			return nil, kerr
		}
		d, kerr := fr.getMpint()
		if kerr != nil {
			return nil, kerr
		}
		if len(q) != info.qsize {
			return nil, &keyParseError{"failed"}
		}
		x, y := elliptic.Unmarshal(info.curve, q)
		if x == nil || !info.curve.IsOnCurve(x, y) {
			return nil, &keyParseError{"failed"}
		}
		if d.Sign() <= 0 {
			return nil, &keyParseError{"failed"}
		}
		// check d corresponds to Q
		gx, gy := info.curve.ScalarBaseMult(padBytes(d.Bytes(), (info.size+7)/8))
		if gx == nil || gx.Cmp(x) != 0 || gy.Cmp(y) != 0 {
			return nil, &keyParseError{"failed"}
		}
		hk.ECDSACurve = string(curveBytes)
		hk.ECDSAQ = append([]byte{}, q...)
		hk.ECDSAD = d
		hk.ecCurve = info.curve
		return hk, nil
	case "ssh-rsa":
		var vals []*big.Int
		for i := 0; i < 6; i++ {
			v, kerr := fr.getMpint()
			if kerr != nil {
				if kerr.kind == "Bad buf_getptr" && i >= 5 {
					break
				}
				if kerr.kind == "Bad buf_getptr" && i == 5 {
					break
				}
				// missing iqmp tolerated?
				if i == 5 {
					break
				}
				return nil, kerr
			}
			vals = append(vals, v)
		}
		if len(vals) < 5 {
			return nil, &keyParseError{"failed"}
		}
		hk.RSAE, hk.RSAN, hk.RSAD, hk.RSAP, hk.RSAQ = vals[0], vals[1], vals[2], vals[3], vals[4]
		if len(vals) >= 6 {
			hk.RSAIQ = vals[5]
		}
		if hk.RSAN.BitLen() < 1024 {
			logMsg("RSA key too short")
			return nil, &keyParseError{"failed"}
		}
		// consistency: p*q==n
		prod := new(big.Int).Mul(hk.RSAP, hk.RSAQ)
		if prod.Cmp(hk.RSAN) != 0 {
			return nil, &keyParseError{"failed"}
		}
		if hk.RSAE.Sign() <= 0 || hk.RSAD.Sign() <= 0 {
			return nil, &keyParseError{"failed"}
		}
		return hk, nil
	default:
		return nil, &keyParseError{"failed"}
	}
}

func padBytes(b []byte, size int) []byte {
	if len(b) >= size {
		return b
	}
	out := make([]byte, size)
	copy(out[size-len(b):], b)
	return out
}

func writeDropbearKey(hk *HostKey) []byte {
	w := &writer{}
	switch hk.Type {
	case "ssh-ed25519":
		w.str("ssh-ed25519")
		w.strBytes(hk.EdPriv)
		w.strBytes(hk.EdPub)
	case "ssh-rsa":
		w.str("ssh-rsa")
		w.mpint(hk.RSAE)
		w.mpint(hk.RSAN)
		w.mpint(hk.RSAD)
		w.mpint(hk.RSAP)
		w.mpint(hk.RSAQ)
		if hk.RSAIQ != nil {
			w.mpint(hk.RSAIQ)
		}
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		w.str(hk.Type)
		w.str(hk.ECDSACurve)
		w.strBytes(hk.ECDSAQ)
		w.mpint(hk.ECDSAD)
	}
	return w.Bytes()
}

func keyTypeDisplay(hk *HostKey) string {
	switch hk.Type {
	case "ssh-rsa":
		return "RSA"
	case "ssh-ed25519":
		return "ed25519"
	case "ecdsa-sha2-nistp256":
		return "ECDSA256"
	case "ecdsa-sha2-nistp384":
		return "ECDSA384"
	case "ecdsa-sha2-nistp521":
		return "ECDSA521"
	}
	return hk.Type
}

func generateHostKey(algo string) (*HostKey, error) {
	switch algo {
	case "ssh-ed25519":
		pub, priv, err := ed25519.GenerateKey(randReader{})
		if err != nil {
			return nil, err
		}
		return &HostKey{Type: "ssh-ed25519", EdPriv: priv, EdPub: pub}, nil
	case "rsa-sha2-256", "ssh-rsa":
		return generateRSA()
	case "ecdsa-sha2-nistp256":
		return generateECDSA("nistp256")
	case "ecdsa-sha2-nistp384":
		return generateECDSA("nistp384")
	case "ecdsa-sha2-nistp521":
		return generateECDSA("nistp521")
	}
	return nil, fmt.Errorf("unknown key type %s", algo)
}

type randReader struct{}

func (randReader) Read(p []byte) (int, error) {
	// use crypto/rand via a helper to avoid import cycle inside expressions
	return readRand(p)
}

func generateRSA() (*HostKey, error) {
	// use crypto/rsa
	key, err := rsaGenerateKey(2048)
	if err != nil {
		return nil, err
	}
	p := key.Primes[0]
	q := key.Primes[1]
	iq := new(big.Int).ModInverse(q, p)
	return &HostKey{
		Type: "ssh-rsa",
		RSAE: big.NewInt(int64(key.PublicKey.E)),
		RSAN: key.PublicKey.N,
		RSAD: key.D,
		RSAP: p,
		RSAQ: q,
		RSAIQ: iq,
	}, nil
}

func generateECDSA(curveName string) (*HostKey, error) {
	info := ecdsaCurves[curveName]
	priv, err := ecdsaGenerateKey(info.curve)
	if err != nil {
		return nil, err
	}
	q := elliptic.Marshal(info.curve, priv.PublicKey.X, priv.PublicKey.Y)
	return &HostKey{
		Type: info.algo,
		ECDSACurve: curveName,
		ECDSAQ: q,
		ECDSAD: priv.D,
		ecCurve: info.curve,
	}, nil
}

// ensure a hostkey for the given negotiated algorithm exists (loading/generating delayed)
// returns key or error reason string
func (sess *session) ensureHostKey(algo string) *HostKey {
	// loaded entries first
	for _, e := range sess.opts.Entries {
		if !e.Loaded {
			continue
		}
		hk, err := parseDropbearKey(e.Data)
		if err != nil {
			continue
		}
		if hk.algoName() == algo {
			return hk
		}
	}
	// delayed entries
	for _, e := range sess.opts.Entries {
		if !e.Delayed {
			continue
		}
		if e.DelayType == "" {
			continue
		}
		// match by algo name: delayed types stored as algo names already
		if delayedAlgoName(e.DelayType) != algo {
			continue
		}
		// try load file if exists
		if data, err := os.ReadFile(e.Path); err == nil {
			hk, err := parseDropbearKey(data)
			if err == nil && hk.algoName() == algo {
				return hk
			}
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		// generate
		hk, err := generateHostKey(algo)
		if err != nil {
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		tmpPath := fmt.Sprintf("%s.tmp%d", e.Path, os.Getpid())
		f, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
		if err != nil {
			logMsg("Couldn't create new file %s: %s", tmpPath, strerrorName(err))
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		_, werr := f.Write(writeDropbearKey(hk))
		f.Close()
		if werr != nil {
			os.Remove(tmpPath)
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		if err := os.Rename(tmpPath, e.Path); err != nil {
			// if rename fails, still use generated key? dropbear would fail
			os.Remove(tmpPath)
			fatalf("Couldn't read or generate hostkey %s", e.Path)
		}
		// ensure perms 0600
		syscall.Chmod(e.Path, 0600)
		return hk
	}
	return nil
}

func delayedAlgoName(t string) string {
	// DelayType stored as key type or algo; normalize
	switch t {
	case "ssh-rsa":
		return "rsa-sha2-256"
	default:
		return t
	}
}

var _ = strings.TrimSpace
var _ = syscall.SIGTERM
EOF
"}

