package main

import (
	"encoding/binary"
	"math/big"
	"math/bits"
)

// ChaCha block implementations (legacy 64-bit nonce / 64-bit counter, and IETF)
func chachaBlock(key []byte, counter uint64, nonce []byte, ietf bool) [64]byte {
	var state [16]uint32
	state[0] = 0x61707865
	state[1] = 0x3320646e
	state[2] = 0x79622d32
	state[3] = 0x6b206574
	for i := 0; i < 8; i++ {
		state[4+i] = binary.LittleEndian.Uint32(key[i*4:])
	}
	if ietf {
		state[12] = uint32(counter)
		// nonce 12 bytes
		state[13] = binary.LittleEndian.Uint32(nonce[0:4])
		state[14] = binary.LittleEndian.Uint32(nonce[4:8])
		state[15] = binary.LittleEndian.Uint32(nonce[8:12])
	} else {
		state[12] = uint32(counter)
		state[13] = uint32(counter >> 32)
		state[14] = binary.LittleEndian.Uint32(nonce[0:4])
		state[15] = binary.LittleEndian.Uint32(nonce[4:8])
	}
	working := state
	qr := func(a, b, c, d int) {
		working[a] += working[b]
		working[d] ^= working[a]
		working[d] = bits.RotateLeft32(working[d], 16)
		working[c] += working[d]
		working[b] ^= working[c]
		working[b] = bits.RotateLeft32(working[b], 12)
		working[a] += working[b]
		working[d] ^= working[a]
		working[d] = bits.RotateLeft32(working[d], 8)
		working[c] += working[d]
		working[b] ^= working[c]
		working[b] = bits.RotateLeft32(working[b], 7)
	}
	for i := 0; i < 10; i++ {
		qr(0, 4, 8, 12)
		qr(1, 5, 9, 13)
		qr(2, 6, 10, 14)
		qr(3, 7, 11, 15)
		qr(0, 5, 10, 15)
		qr(1, 6, 11, 12)
		qr(2, 7, 8, 13)
		qr(3, 4, 9, 14)
	}
	var out [64]byte
	for i := 0; i < 16; i++ {
		binary.LittleEndian.PutUint32(out[i*4:], working[i]+state[i])
	}
	return out
}

type chachaStream struct {
	key     []byte
	nonce   []byte
	ietf    bool
	counter uint64
	block   [64]byte
	pos     int
}

func newChachaStream(key, nonce []byte, ietf bool, counter uint64) *chachaStream {
	s := &chachaStream{key: append([]byte{}, key...), nonce: append([]byte{}, nonce...), ietf: ietf, counter: counter, pos: 64}
	return s
}
func (s *chachaStream) xor(dst, src []byte) {
	for i := range src {
		if s.pos >= 64 {
			s.block = chachaBlock(s.key, s.counter, s.nonce, s.ietf)
			s.counter++
			s.pos = 0
		}
		dst[i] = src[i] ^ s.block[s.pos]
		s.pos++
	}
}

// Poly1305
var (
	polyP, _ = new(big.Int).SetString("3fffffffffffffffffffffffffffffffb", 16)
	polyPow2_128, _ = new(big.Int).SetString("100000000000000000000000000000000", 16)
)

func poly1305MAC(key []byte, msg []byte) []byte {
	// key 32 bytes: r (16 LE, clamped) and s (16 LE)
	rBytes := make([]byte, 16)
	copy(rBytes, key[:16])
	rBytes[3] &= 15
	rBytes[7] &= 15
	rBytes[11] &= 15
	rBytes[15] &= 15
	rBytes[4] &= 252
	rBytes[8] &= 252
	rBytes[12] &= 252
	r := leToBig(rBytes)
	s := leToBig(key[16:32])
	acc := big.NewInt(0)
	for i := 0; i < len(msg); i += 16 {
		end := i + 16
		if end > len(msg) {
			end = len(msg)
		}
		chunk := msg[i:end]
		nBytes := append(append([]byte{}, chunk...), 0x01)
		n := leToBig(nBytes)
		acc.Add(acc, n)
		acc.Mul(acc, r)
		acc.Mod(acc, polyP)
	}
	acc.Add(acc, s)
	acc.Mod(acc, polyPow2_128)
	out := bigToLE(acc, 16)
	return out
}

func leToBig(b []byte) *big.Int {
	rev := make([]byte, len(b))
	for i, v := range b {
		rev[len(b)-1-i] = v
	}
	return new(big.Int).SetBytes(rev)
}
func bigToLE(v *big.Int, size int) []byte {
	b := v.Bytes()
	out := make([]byte, size)
	for i := 0; i < len(b) && i < size; i++ {
		out[i] = b[len(b)-1-i]
	}
	return out
}
EOF
"}

