// ChaCha block implementations (legacy 64-bit nonce / 64-bit counter, and IETF)
func chachaBlock(key []byte, counter uint64, nonce []byte, ietf bool) [64]byte {
	var state [16]uint32
	state[0] = 0x61707865
	state[1] = 0x3320646e
	state[2] = 0x79622d32
	state[3] = 0x6b206574
	for i := 0; i < 8; i++ {
