func newCipherState(algo string, key, iv, macKey []byte) *cipherState {
	cs := &cipherState{algo: algo, key: key, iv: iv, macKey: macKey, blockSize: 8}
	if algo == "aes128-ctr" || algo == "aes256-ctr" {
		cs.blockSize = 16
	}
	return cs
