func (cs *cipherState) aesEncStream() (cipher.Stream, error) {
	if cs.aesStream != nil {
		return cs.aesStream, nil
	}
	block, err := aes.NewCipher(cs.key)
	if err != nil {
		return nil, err
	}
	cs.aesStream = cipher.NewCTR(block, append([]byte{}, cs.iv...))
	return cs.aesStream, nil
}
// Decrypt side needs its own stream object; we keep separate cipherState instances for send/recv,
// each lazily creates its CTR stream (same algorithm for enc/dec)

var chaVariant = func() int {
	v := os.Getenv("DBCHACHA_VARIANT")
	if v == "" {
		return 2
	}
	n, _ := strconv.Atoi(v)
	if n == 0 {
		return 2
	}
	return n
}()

func chachaKeys(cs *cipherState) (mainKey, headerKey []byte) {
	if chaVariant == 5 {
		return cs.key[32:64], cs.key[0:32]
	}
	// guess: main first 32, header next 32
	return cs.key[0:32], cs.key[32:64]
}

func chachaNonce(cs *cipherState, seq uint32) []byte {
	var nb [8]byte
	switch chaVariant {
	case 3, 4:
		binary.LittleEndian.PutUint64(nb[:], uint64(seq))
	default:
		binary.BigEndian.PutUint64(nb[:], uint64(seq))
	}
