		return t.readPacketPlain()
	}
	switch cs.algo {
	case "chacha20-poly1305@openssh.com":
		return t.readPacketChacha(cs)
	case "aes128-ctr", "aes256-ctr":
		return t.readPacketAES(cs)
	}
	return nil, fmt.Errorf("unknown cipher")
}

func (t *transport) readPacketPlain() ([]byte, error) {
	var lenBuf [4]byte
	if err := readExact(t.br, lenBuf[:]); err != nil {
		return nil, err
