	pktLen := binary.BigEndian.Uint32(lenBuf[:])
	if pktLen > maxPacketSize || pktLen < 12 {
		fatalf("Integrity error (bad packet size %d)", pktLen)
	}
	body := make([]byte, pktLen)
	if err := readExact(t.br, body); err != nil {
		return nil, err
	}
	t.recvSeq++
	padLen := int(body[0])
	if padLen < 4 || int(pktLen)-1-padLen < 0 {
		fatalf("Integrity error")
	}
	payload := body[1 : int(pktLen)-padLen]
	// copy payload
	out := append([]byte{}, payload...)
	return out, nil
}

func (t *transport) readPacketAES(cs *cipherState) ([]byte, error) {
