	var polyKey []byte
	var body []byte
	if ietf {
		s := newChachaStream(mainKey, nonceIETF, true, 0)
		polyKeyBlock := make([]byte, 64)
		zeros := make([]byte, 64)
		s.xor(polyKeyBlock, zeros)
		polyKey = polyKeyBlock[:32]
		// payload stream starts at counter 1; our stream already advanced one block
		body = make([]byte, pktLen)
		s.xor(body, encBody)
	} else {
		s := newChachaStream(mainKey, nonce, false, 0)
		polyKeyBlock := make([]byte, 64)
		zeros := make([]byte, 64)
		s.xor(polyKeyBlock, zeros)
		polyKey = polyKeyBlock[:32]
		body = make([]byte, pktLen)
		s.xor(body, encBody)
	}
