		var out bytes.Buffer
		var lb [4]byte
		binary.BigEndian.PutUint32(lb[:], uint32(pktLen))
		out.Write(lb[:])
		out.Write(body)
		_, err := t.conn.Write(out.Bytes())
		if err == nil {
			t.sendSeq++
		}
		return err
	}
	switch cs.algo {
	case "aes128-ctr", "aes256-ctr":
		stream, err := cs.aesEncStream()
		if err != nil {
			return err
		}
		encBody := make([]byte, len(body))
		stream.XORKeyStream(encBody, body)
		var lb [4]byte
		binary.BigEndian.PutUint32(lb[:], uint32(pktLen))
		var mac []byte
		if len(cs.macKey) > 0 {
			m := hmac.New(sha256.New, cs.macKey)
			var seqBuf [4]byte
			binary.BigEndian.PutUint32(seqBuf[:], t.sendSeq)
			m.Write(seqBuf[:])
			m.Write(lb[:])
			m.Write(body)
			mac = m.Sum(nil)
		}
		var out bytes.Buffer
		out.Write(lb[:])
		out.Write(encBody)
		if mac != nil {
			out.Write(mac)
		}
		_, err = t.conn.Write(out.Bytes())
		if err == nil {
			t.sendSeq++
		}
		return err
	case "chacha20-poly1305@openssh.com":
		mainKey, headerKey := chachaKeys(cs)
		ietf := chaVariant == 6
		var lb [4]byte
		binary.BigEndian.PutUint32(lb[:], uint32(pktLen))
		var encLen []byte
		var encBody []byte
		var polyKey []byte
		if ietf {
			nonce := chachaIETFNonce(cs, t.sendSeq)
			hs := newChachaStream(headerKey, nonce, true, 0)
			encLen = make([]byte, 4)
			hs.xor(encLen, lb[:])
			ms := newChachaStream(mainKey, nonce, true, 0)
			polyBlock := make([]byte, 64)
			ms.xor(polyBlock, make([]byte, 64))
			polyKey = polyBlock[:32]
			encBody = make([]byte, len(body))
			ms.xor(encBody, body)
		} else {
			nonce := chachaNonce(cs, t.sendSeq)
			hs := newChachaStream(headerKey, nonce, false, 0)
			encLen = make([]byte, 4)
			hs.xor(encLen, lb[:])
			ms := newChachaStream(mainKey, nonce, false, 0)
			polyBlock := make([]byte, 64)
			ms.xor(polyBlock, make([]byte, 64))
			polyKey = polyBlock[:32]
			encBody = make([]byte, len(body))
			ms.xor(encBody, body)
		}
		macData := append(append([]byte{}, encLen...), encBody...)
		tag := poly1305MAC(polyKey, macData)
		var out bytes.Buffer
		out.Write(encLen)
		out.Write(encBody)
		out.Write(tag)
		_, err := t.conn.Write(out.Bytes())
		if err == nil {
			t.sendSeq++
		}
		return err
	}
	return fmt.Errorf("unknown cipher for write")
}

func (t *transport) compressPayload(payload []byte) ([]byte, error) {
	if t.compWriter == nil {
		zw, err := newZlibWriterState()
		if err != nil {
			return nil, err
		}
		t.compWriter = zw
	}
	return t.compWriter.compress(payload)
}

// send raw packet (before encryption activation) - same as writePacket when cipher nil.
// Writing NEWKEYS requires seq handling etc, handled via writePacket with old cipher state.

func hashBytes(hashFn func() hash.Hash, parts ...[]byte) []byte {
	h := hashFn()
	for _, p := range parts {
		h.Write(p)
	}
	return h.Sum(nil)
}

var _ = io.EOF
EOF
