)

type zlibWriterState struct {
	buf *bytes.Buffer
	w *zlib.Writer
}

func newZlibWriterState() (*zlibWriterState, error) {
	var buf bytes.Buffer
	w, err := zlib.NewWriterLevel(&buf, zlib.DefaultCompression)
	if err != nil {
		return nil, err
	}
	return &zlibWriterState{buf: &buf, w: w}, nil
}

func (z *zlibWriterState) compress(payload []byte) ([]byte, error) {
	z.buf.Reset()
	if _, err := z.w.Write(payload); err != nil {
