{"command":"cat > kex.go <<'EOF'
package main

import (
	"crypto"
	"crypto/ecdh"
	"crypto/elliptic"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/binary"
	"fmt"
	"hash"
	"math/big"
	"strings"
)

const (
	kexList = "sntrup761x25519-sha512,sntrup761x25519-sha512@openssh.com,mlkem768x25519-sha256,curve25519-sha256,curve25519-sha256@libssh.org,ecdh-sha2-nistp521,ecdh-sha2-nistp384,ecdh-sha2-nistp256,diffie-hellman-group14-sha256,kexguess2@matt.ucc.asn.au,kex-strict-s-v00@openssh.com"
	encList = "chacha20-poly1305@openssh.com,aes256-ctr,aes128-ctr"
	macList = "hmac-sha2-256"
	compCTOS = "none"
	compSTOC = "zlib@openssh.com,zlib,none"
	sigAlgs = "ssh-ed25519,sk-ssh-ed25519@openssh.com,ecdsa-sha2-nistp256,ecdsa-sha2-nistp384,ecdsa-sha2-nistp521,sk-ecdsa-sha2-nistp256@openssh.com,rsa-sha2-256"
)

func (sess *session) hostkeyAlgoList() string {
	present := make(map[string]bool)
	for _, e := range sess.opts.Entries {
		if e.Loaded {
			if hk, err := parseDropbearKey(e.Data); err == nil {
				present[hk.algoName()] = true
			}
		}
		if e.Delayed && e.DelayType != "" {
			// skip ecdsa delayed default if a loaded ecdsa of another curve exists?
			// The caller (loadHostkeys) handles skipping; here entries already filtered
			present[delayedAlgoName(e.DelayType)] = true
		}
	}
	var order = []string{"ssh-ed25519", "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521", "rsa-sha2-256"}
	var out []string
	for _, a := range order {
		if present[a] {
			out = append(out, a)
		}
	}
	return strings.Join(out, ",")
}

func (sess *session) makeKexInit() []byte {
	w := &writer{}
	w.byte(msgKexInit)
	w.Write(randBytes(16))
	w.str(kexList)
	w.str(sess.hostkeyAlgoList())
	w.str(encList) // c->s
	w.str(encList) // s->c
	w.str(macList)
	w.str(macList)
	w.str(compCTOS)
	w.str(compSTOC)
	w.str("") // languages c->s
	w.str("") // languages s->c
	w.bool(false)
	w.uint32(0)
	return w.Bytes()
}

type negotiated struct {
	kex string
	hostkey string
	encCTOS, encSTOC string
	macCTOS, macSTOC string
	compCTOS, compSTOC string
	hashFn func() hash.Hash
	clientExtInfo bool
	firstKexFollows bool
}

func hashForKex(kex string) func() hash.Hash {
	switch kex {
	case "ecdh-sha2-nistp384":
		return sha512.New384
	case "ecdh-sha2-nistp521":
		return sha512.New
	default:
		return sha256.New
	}
}

// group14 prime from RFC 3526
var group14Prime *big.Int
func init() {
	pHex := "FFFFFFFFFFFFFFFFC90FDAA22168C234C4C6628B80DC1CD1" +
		"29024E088A67CC74020BBEA63B139B22514A08798E3404DD" +
		"EF9519B3CD3A431B302B0A6DF25F14374FE1356D6D51C245" +
		"E485B576625E7EC6F44C42E9A637ED6B0BFF5CB6F406B7ED" +
		"EE386BFB5A899FA5AE9F24117C4B1FE649286651ECE45B3D" +
		"C2007CB8A163BF0598DA48361C55D39A69163FA8FD24CF5F" +
		"83655D23DCA3AD961C62F356208552BB9ED529077096966D" +
		"670C354E4ABC9804F1746C08CA18217C32905E462E36CE3B" +
		"E39E772C180E86039B2783A2EC07A28FB5C55DF06F4C52C9" +
		"DE2BCBF6955817183995497CEA956AE515D2261898FA0510" +
		"15728E5A8AACAA68FFFFFFFFFFFFFFFF"
	group14Prime, _ = new(big.Int).SetString(pHex, 16)
}

// handleKex performs a key exchange. If isFirst, sessionID set from H; else retained.
// It expects client KEXINIT payload already read (clientKex).
// It will read the KEX specific packet and NEWKEYS from client, send reply and NEWKEYS.
// discardGuess: if client set first_kex_follows and guess wrong, one packet should be discarded
func (t *transport) handleKex(clientKexPayload []byte) error {
	sess := t.sess
	// parse client kexinit
	r := newReader(clientKexPayload)
	if r.byte() != msgKexInit {
		return fmt.Errorf("bad kexinit")
	}
	r.bytes(16)
	kexAlgos := r.str()
	hostkeyAlgos := r.str()
	encCTOS := r.str()
	encSTOC := r.str()
	macCTOS := r.str()
	macSTOC := r.str()
	compCTOSList := r.str()
	compSTOCList := r.str()
	r.str(); r.str() // languages
	firstKexFollows := r.bool()
	_ = firstKexFollows
	if r.err != nil {
		fatalf("KEX error")
	}

	clientExtInfo := quoteListContains(kexAlgos, "ext-info-c")
	strictClient := quoteListContains(kexAlgos, "kex-strict-c-v00@openssh.com")

	serverHostList := sess.hostkeyAlgoList()
	neg := &negotiated{clientExtInfo: clientExtInfo, firstKexFollows: firstKexFollows}
	var ok bool
	// kex: need filter pseudo algorithms from client list for matching
	neg.kex, ok = negotiateFiltered(kexAlgos, kexList, map[string]bool{"ext-info-c": true, "kex-strict-c-v00@openssh.com": true})
	if !ok {
		fatalf("No matching algo kex")
	}
	neg.hostkey, ok = negotiate(hostkeyAlgos, serverHostList)
	if !ok {
		fatalf("No matching algo hostkey")
	}
	neg.encCTOS, ok = negotiate(encCTOS, encList)
	if !ok {
		fatalf("No matching algo enc c->s")
	}
	neg.encSTOC, ok = negotiate(encSTOC, encList)
	if !ok {
		fatalf("No matching algo enc s->c")
	}
	// MAC only relevant if cipher is not AEAD; but SSH negotiation still? Original checks mac c->s even when? 
	// Test showed when chacha chosen, mismatched mac was tolerated (client didn't abort, server presumably still checked? Actually OpenSSH itself would not consider it fatal because MAC is implicit. But server log for aes+hmac-sha1 gave mac c->s. So if cipher is AEAD, skip mac check.)
	isAEAD := neg.encCTOS == "chacha20-poly1305@openssh.com"
	isAEADStoc := neg.encSTOC == "chacha20-poly1305@openssh.com"
	if !isAEAD {
		neg.macCTOS, ok = negotiate(macCTOS, macList)
		if !ok {
			fatalf("No matching algo mac c->s")
		}
	} else {
		neg.macCTOS, _ = negotiate(macCTOS, macList)
	}
	if !isAEADStoc {
		neg.macSTOC, ok = negotiate(macSTOC, macList)
		if !ok {
			fatalf("No matching algo mac s->c")
		}
	} else {
		neg.macSTOC, _ = negotiate(macSTOC, macList)
	}
	neg.compCTOS, ok = negotiate(compCTOSList, compCTOS)
	if !ok {
		fatalf("No matching algo comp c->s")
	}
	neg.compSTOC, ok = negotiate(compSTOCList, compSTOC)
	if !ok {
		fatalf("No matching algo comp s->c")
	}
	neg.hashFn = hashForKex(neg.kex)

	if !t.firstKexDone {
		if strictClient {
			t.strict = true
		}
	}

	// Determine if a guessed packet needs discarding
	guessWrong := false
	if firstKexFollows {
		// client's guessed algorithms are first entries in its lists (raw first, not filtered)
		gKex := firstListEntry(kexAlgos)
		gHost := firstListEntry(hostkeyAlgos)
		if gKex != neg.kex || gHost != neg.hostkey {
			guessWrong = true
		}
	}

	// check supported kex implementation
	switch neg.kex {
	case "curve25519-sha256", "curve25519-sha256@libssh.org",
		"ecdh-sha2-nistp256", "ecdh-sha2-nistp384", "ecdh-sha2-nistp521",
		"diffie-hellman-group14-sha256":
		// ok
	case "sntrup761x25519-sha512", "sntrup761x25519-sha512@openssh.com", "mlkem768x25519-sha256":
		// not yet implemented; attempt PQ path if implemented later
		if !t.handlePQKex(neg, clientKexPayload, guessWrong, clientExtInfo) {
			fatalf("No matching algo kex")
		}
		return nil
	default:
		fatalf("No matching algo kex")
	}

	// Read KEX init packet (30)
	var kexPacket []byte
	for {
		p, err := t.readPacket()
		if err != nil {
			return err
		}
		if len(p) == 0 {
			continue
		}
		if guessWrong {
			// discard this packet per first_kex_follows
			guessWrong = false
			continue
		}
		if p[0] == msgIgnore || p[0] == msgDebug || p[0] == msgExtInfo {
			if t.strict && !t.firstKexDone {
				// strict kex forbids extraneous messages during initial kex except... 
				// EXT_INFO not allowed before newkeys during initial kex? ignore packets also prohibited
				fatalf("KEX error")
			}
			continue
		}
		if p[0] != msgKexECDHInit {
			fatalf("KEX error")
		}
		kexPacket = p
		break
	}

	kr := newReader(kexPacket)
	kr.byte()
	var sharedSecret *big.Int
	var sharedBytes []byte // for mpint encoding, use big int
	var clientPub, serverPub []byte // string-encoded parts for hash (raw bytes of string contents for curve/ecdh; mpint for DH handled separately)
	var eValue, fValue *big.Int // DH
	isDH := neg.kex == "diffie-hellman-group14-sha256"

	if isDH {
		eValue = kr.mpint()
		if kr.err != nil || eValue.Sign() <= 0 || eValue.Cmp(group14Prime) >= 0 {
			fatalf("KEX error")
		}
		// generate ephemeral: 256 bits random exponent
		xBytes := randBytes(32)
		x := new(big.Int).SetBytes(xBytes)
		fValue = new(big.Int).Exp(big.NewInt(2), x, group14Prime)
		sharedSecret = new(big.Int).Exp(eValue, x, group14Prime)
		sharedBytes = nil
		_ = sharedBytes
	} else if neg.kex == "curve25519-sha256" || neg.kex == "curve25519-sha256@libssh.org" {
		clientPub = kr.strBytes()
		if kr.err != nil || len(clientPub) != 32 {
			fatalf("KEX error")
		}
		priv, err := ecdh.X25519().GenerateKey(randReader{})
		if err != nil {
			fatalf("KEX error")
		}
		pub, err := ecdh.X25519().NewPublicKey(clientPub)
		if err != nil {
			fatalf("KEX error")
		}
		secret, err := priv.ECDH(pub)
		if err != nil {
			fatalf("KEX error")
		}
		serverPub = priv.PublicKey().Bytes()
		sharedSecret = new(big.Int).SetBytes(secret)
		// For curve25519, mpint encoding of shared secret: SSH mpints with leading zero if high bit, but if secret has leading zeros they are stripped? The K value as integer.
	} else {
		// ECDH NIST
		clientPub = kr.strBytes()
		if kr.err != nil {
			fatalf("KEX error")
		}
		var curve ecdhCurve
		switch neg.kex {
		case "ecdh-sha2-nistp256":
			curve = ecdh.P256()
		case "ecdh-sha2-nistp384":
			curve = ecdh.P384()
		case "ecdh-sha2-nistp521":
			curve = ecdh.P521()
		}
		priv, err := curve.GenerateKey(randReader{})
		if err != nil {
			fatalf("KEX error")
		}
		pub, err := curve.NewPublicKey(clientPub)
		if err != nil {
			fatalf("KEX error")
		}
		secret, err := priv.ECDH(pub)
		if err != nil {
			fatalf("KEX error")
		}
		serverPub = priv.PublicKey().Bytes()
		sharedSecret = new(big.Int).SetBytes(secret)
	}

	// host key
	hk := sess.ensureHostKey(neg.hostkey)
	if hk == nil {
		fatalf("No matching algo hostkey")
	}
	hostBlob := hk.publicBlob()

	// Exchange hash
	hw := &writer{}
	hw.str(t.clientVersion)
	hw.str(serverVersion)
	hw.strBytes(clientKexPayload)
	hw.strBytes(t.serverKexPayload)
	hw.strBytes(hostBlob)
	if isDH {
		hw.mpint(eValue)
		hw.mpint(fValue)
	} else {
		hw.strBytes(clientPub)
		hw.strBytes(serverPub)
	}
	hw.mpint(sharedSecret)
	H := neg.hashFn()
	H.Write(hw.Bytes())
	exchangeHash := H.Sum(nil)

	if !t.firstKexDone {
		t.sessionID = append([]byte{}, exchangeHash...)
	}

	// signature
	sigBlob, err := hk.sign(randReader{}, exchangeHash, neg.hostkey)
	if err != nil {
		fatalf("KEX error")
	}

	// Reply
	rw := &writer{}
	rw.byte(msgKexECDHReply)
	rw.strBytes(hostBlob)
	if isDH {
		rw.mpint(fValue)
	} else {
		rw.strBytes(serverPub)
	}
	rw.strBytes(sigBlob)
	if err := t.writePacket(rw.Bytes()); err != nil {
		return err
	}

	// Derive keys
	derive := func(letter byte, needed int) []byte {
		return deriveKey(neg.hashFn, sharedSecret, exchangeHash, letter, t.sessionID, needed)
	}

	// key sizes
	var ctosKeyLen, stocKeyLen, ctosIVLen, stocIVLen int
	var ctosMacLen, stocMacLen int
	getCipherLens := func(algo string) (keyLen, ivLen int) {
		switch algo {
		case "chacha20-poly1305@openssh.com":
			return 64, 8
		case "aes256-ctr":
			return 32, 16
		case "aes128-ctr":
			return 16, 16
		}
		return 0, 0
	}
	ctosKeyLen, ctosIVLen = getCipherLens(neg.encCTOS)
	stocKeyLen, stocIVLen = getCipherLens(neg.encSTOC)
	if neg.encCTOS != "chacha20-poly1305@openssh.com" {
		ctosMacLen = 32
	}
	if neg.encSTOC != "chacha20-poly1305@openssh.com" {
		stocMacLen = 32
	}

	ivCTOS := derive('A', ctosIVLen)
	ivSTOC := derive('B', stocIVLen)
	keyCTOS := derive('C', ctosKeyLen)
	keySTOC := derive('D', stocKeyLen)
	var macCTOS, macSTOC []byte
	if ctosMacLen > 0 {
		macCTOS = derive('E', ctosMacLen)
	}
	if stocMacLen > 0 {
		macSTOC = derive('F', stocMacLen)
	}

	// Send NEWKEYS (with old cipher)
	nw := &writer{}
	nw.byte(msgNewKeys)
	if err := t.writePacket(nw.Bytes()); err != nil {
		return err
	}
	// activate send cipher
	t.sendCipher = newCipherState(neg.encSTOC, keySTOC, ivSTOC, macSTOC)
