	var ok bool
	// kex: need filter pseudo algorithms from client list for matching
	neg.kex, ok = negotiateFiltered(kexAlgos, kexList, map[string]bool{"ext-info-c": true, "kex-strict-c-v00@openssh.com": true})
	if !ok {
		fatalf("No matching algo kex")
	}
	neg.hostkey, ok = negotiate(hostkeyAlgos, serverHostList)
	if !ok {
		fatalf("No matching algo hostkey")
	}
	neg.encCTOS, ok = negotiate(encCTOS, encList)
	if !ok {
		fatalf("No matching algo enc c->s")
	}
	neg.encSTOC, ok = negotiate(encSTOC, encList)
	if !ok {
		fatalf("No matching algo enc s->c")
	}
