	// Test showed when chacha chosen, mismatched mac was tolerated (client didn't abort, server presumably still checked? Actually OpenSSH itself would not consider it fatal because MAC is implicit. But server log for aes+hmac-sha1 gave mac c->s. So if cipher is AEAD, skip mac check.)
	isAEAD := neg.encCTOS == "chacha20-poly1305@openssh.com"
	isAEADStoc := neg.encSTOC == "chacha20-poly1305@openssh.com"
	if !isAEAD {
		neg.macCTOS, ok = negotiate(macCTOS, macList)
		if !ok {
			fatalf("No matching algo mac c->s")
		}
	} else {
		neg.macCTOS, _ = negotiate(macCTOS, macList)
	}
	if !isAEADStoc {
		neg.macSTOC, ok = negotiate(macSTOC, macList)
		if !ok {
			fatalf("No matching algo mac s->c")
		}
	} else {
		neg.macSTOC, _ = negotiate(macSTOC, macList)
	}
	neg.compCTOS, ok = negotiate(compCTOSList, compCTOS)
	if !ok {
		fatalf("No matching algo comp c->s")
	}
	neg.compSTOC, ok = negotiate(compSTOCList, compSTOC)
	if !ok {
		fatalf("No matching algo comp s->c")
	}
