	var sharedSecret *big.Int
	var sharedBytes []byte // for mpint encoding, use big int
	var clientPub, serverPub []byte // string-encoded parts for hash (raw bytes of string contents for curve/ecdh; mpint for DH handled separately)
	var eValue, fValue *big.Int // DH
