		eValue = kr.mpint()
		if kr.err != nil || eValue.Sign() <= 0 || eValue.Cmp(group14Prime) >= 0 {
			fatalf("KEX error")
		}
		// generate ephemeral: 256 bits random exponent
		xBytes := randBytes(32)
		x := new(big.Int).SetBytes(xBytes)
		fValue = new(big.Int).Exp(big.NewInt(2), x, group14Prime)
		sharedSecret = new(big.Int).Exp(eValue, x, group14Prime)
		sharedBytes = nil
		_ = sharedBytes
	} else if neg.kex == "curve25519-sha256" || neg.kex == "curve25519-sha256@libssh.org" {
