		if err != nil {
			fatalf("KEX error")
		}
		pub, err := ecdh.X25519().NewPublicKey(clientPub)
		if err != nil {
			fatalf("KEX error")
		}
		secret, err := priv.ECDH(pub)
		if err != nil {
			fatalf("KEX error")
		}
		serverPub = priv.PublicKey().Bytes()
		sharedSecret = new(big.Int).SetBytes(secret)
		// For curve25519, mpint encoding of shared secret: SSH mpints with leading zero if high bit, but if secret has leading zeros they are stripped? The K value as integer.
	} else {
