		switch neg.kex {
		case "ecdh-sha2-nistp256":
			curve = ecdh.P256()
		case "ecdh-sha2-nistp384":
			curve = ecdh.P384()
		case "ecdh-sha2-nistp521":
			curve = ecdh.P521()
		}
		priv, err := curve.GenerateKey(randReader{})
		if err != nil {
			fatalf("KEX error")
		}
		pub, err := curve.NewPublicKey(clientPub)
		if err != nil {
			fatalf("KEX error")
		}
		secret, err := priv.ECDH(pub)
		if err != nil {
			fatalf("KEX error")
		}
		serverPub = priv.PublicKey().Bytes()
		sharedSecret = new(big.Int).SetBytes(secret)
	}

