	hk := sess.ensureHostKey(neg.hostkey)
	if hk == nil {
		fatalf("No matching algo hostkey")
	}
	hostBlob := hk.publicBlob()

	// Exchange hash
	hw := &writer{}
	hw.str(t.clientVersion)
	hw.str(serverVersion)
	hw.strBytes(clientKexPayload)
	hw.strBytes(t.serverKexPayload)
	hw.strBytes(hostBlob)
	if isDH {
		hw.mpint(eValue)
		hw.mpint(fValue)
	} else {
		hw.strBytes(clientPub)
		hw.strBytes(serverPub)
