	rw := &writer{}
	rw.byte(msgKexECDHReply)
	rw.strBytes(hostBlob)
	if isDH {
		rw.mpint(fValue)
	} else {
		rw.strBytes(serverPub)
	}
	rw.strBytes(sigBlob)
	if err := t.writePacket(rw.Bytes()); err != nil {
		return err
	}

	// Derive keys
	derive := func(letter byte, needed int) []byte {
		return deriveKey(neg.hashFn, sharedSecret, exchangeHash, letter, t.sessionID, needed)
	}

	// key sizes
	var ctosKeyLen, stocKeyLen, ctosIVLen, stocIVLen int
	var ctosMacLen, stocMacLen int
	getCipherLens := func(algo string) (keyLen, ivLen int) {
		switch algo {
		case "chacha20-poly1305@openssh.com":
			return 64, 8
		case "aes256-ctr":
			return 32, 16
		case "aes128-ctr":
