	}
	if stocMacLen > 0 {
		macSTOC = derive('F', stocMacLen)
	}

	// Send NEWKEYS (with old cipher)
	nw := &writer{}
	nw.byte(msgNewKeys)
	if err := t.writePacket(nw.Bytes()); err != nil {
		return err
	}
	// activate send cipher
	t.sendCipher = newCipherState(neg.encSTOC, keySTOC, ivSTOC, macSTOC)
	if t.strict && !t.firstKexDone {
		t.sendSeq = 0
	}
	// compression s->c
	t.compAlgo = neg.compSTOC
	if neg.compSTOC == "zlib" {
		t.compActive = true
		t.compWriter = nil
	} else {
		// zlib@openssh.com activates after auth, or "none"
		t.compActive = false
		t.compWriter = nil
	}

	// Read client NEWKEYS packet (still with old receive cipher)
	for {
		p, err := t.readPacket()
		if err != nil {
			return err
		}
		if len(p) > 0 && p[0] == msgNewKeys {
			break
		}
		if len(p) > 0 && (p[0] == msgIgnore || p[0] == msgDebug) {
			continue
		}
		if len(p) == 0 {
			continue
		}
