	t.recvCipher = newCipherState(neg.encCTOS, keyCTOS, ivCTOS, macCTOS)
	if t.strict && !t.firstKexDone {
		t.recvSeq = 0
	}
	t.firstKexDone = true

	// EXT_INFO
	if clientExtInfo {
		ew := &writer{}
		ew.byte(msgExtInfo)
		ew.uint32(1)
		ew.str("server-sig-algs")
		ew.str(sigAlgs)
		if err := t.writePacket(ew.Bytes()); err != nil {
			return err
		}
	}

