package main

import (
	"bufio"
	"os"
	"strconv"
	"strings"
)

type PasswdEntry struct {
	Name   string
	Passwd string
	UID    int
	GID    int
	Gecos  string
	Home   string
	Shell  string
}

func lookupUser(name string) *PasswdEntry {
	f, err := os.Open("/etc/passwd")
	if err != nil {
		return nil
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.Split(line, ":")
		if len(parts) < 7 {
			continue
		}
		if parts[0] != name {
			continue
		}
		uid, _ := strconv.Atoi(parts[2])
		gid, _ := strconv.Atoi(parts[3])
		return &PasswdEntry{
			Name: parts[0], Passwd: parts[1], UID: uid, GID: gid,
			Gecos: parts[4], Home: parts[5], Shell: parts[6],
		}
	}
	return nil
}

type GroupEntry struct {
	Name string
	Passwd string
	GID int
	Members []string
}

func lookupGroupByName(name string) *GroupEntry {
	return lookupGroup(name, -1)
}
func lookupGroupByID(gid int) *GroupEntry {
	return lookupGroup("", gid)
}

func lookupGroup(name string, gid int) *GroupEntry {
	f, err := os.Open("/etc/group")
	if err != nil {
		return nil
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.Split(line, ":")
		if len(parts) < 4 {
			continue
		}
		g, _ := strconv.Atoi(parts[2])
		if gid >= 0 {
			if g != gid {
				continue
			}
		} else if parts[0] != name {
			continue
		}
		var members []string
		if parts[3] != "" {
			members = strings.Split(parts[3], ",")
		}
		return &GroupEntry{Name: parts[0], Passwd: parts[1], GID: g, Members: members}
	}
	return nil
}

func allGroups() []*GroupEntry {
	f, err := os.Open("/etc/group")
	if err != nil {
		return nil
	}
	defer f.Close()
	var out []*GroupEntry
	sc := bufio.NewScanner(f)
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.Split(line, ":")
		if len(parts) < 4 {
			continue
		}
		g, _ := strconv.Atoi(parts[2])
		var members []string
		if parts[3] != "" {
			members = strings.Split(parts[3], ",")
		}
		out = append(out, &GroupEntry{Name: parts[0], Passwd: parts[1], GID: g, Members: members})
	}
	return out
}

func userInGroup(user *PasswdEntry, gid int) bool {
	if user.GID == gid {
		return true
	}
	g := lookupGroupByID(gid)
	if g == nil {
		return false
	}
	for _, m := range g.Members {
		if m == user.Name {
			return true
		}
	}
	return false
}

func supplementaryGids(user *PasswdEntry) []uint32 {
	seen := make(map[int]bool)
	var out []uint32
	for _, g := range allGroups() {
		for _, m := range g.Members {
			if m == user.Name && !seen[g.GID] {
				seen[g.GID] = true
				out = append(out, uint32(g.GID))
			}
		}
	}
	return out
}

// shadow entry
type ShadowEntry struct {
	Name string
	Passwd string
	Fields []string
}

func lookupShadow(name string) *ShadowEntry {
	data, err := os.ReadFile("/etc/shadow")
	if err != nil {
		return nil
	}
	for _, line := range strings.Split(string(data), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Split(line, ":")
		if len(parts) < 2 {
			continue
		}
		if parts[0] == name {
			return &ShadowEntry{Name: parts[0], Passwd: parts[1], Fields: parts}
		}
	}
	return nil
}
