package main

import (
	"crypto"
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"fmt"
	"math/big"
	"os"
	"path/filepath"
	"strings"
	"syscall"
)

type PubKey struct {
	Type string // blob type
	Blob []byte
	// RSA
	E, N *big.Int
	// ED
	EdPub []byte
	// ECDSA
	Curve string
	Q     []byte
	// SK
	App string
	IsSK bool
}

func parsePubKeyBlob(blob []byte) (*PubKey, error) {
	r := newReader(blob)
	typ := r.str()
	pk := &PubKey{Type: typ, Blob: append([]byte{}, blob...)}
	switch typ {
	case "ssh-rsa":
		pk.E = r.mpint()
		pk.N = r.mpint()
	case "ssh-ed25519":
		pk.EdPub = r.strBytes()
		if len(pk.EdPub) != 32 {
			return nil, fmt.Errorf("bad ed pub")
		}
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		pk.Curve = r.str()
		pk.Q = r.strBytes()
	case "sk-ssh-ed25519@openssh.com":
		pk.IsSK = true
		pk.EdPub = r.strBytes()
		pk.App = r.str()
	case "sk-ecdsa-sha2-nistp256@openssh.com":
		pk.IsSK = true
		pk.Curve = r.str()
		pk.Q = r.strBytes()
		pk.App = r.str()
	default:
		return nil, fmt.Errorf("unsupported key type %s", typ)
	}
	if r.err != nil {
		return nil, r.err
	}
	return pk, nil
}

func (pk *PubKey) fingerprint() string {
	return fingerprint(pk.Blob)
}

func (pk *PubKey) equal(other *PubKey) bool {
	if pk.Type != other.Type {
		return false
	}
	switch pk.Type {
	case "ssh-rsa":
		return pk.E.Cmp(other.E) == 0 && pk.N.Cmp(other.N) == 0
	case "ssh-ed25519", "sk-ssh-ed25519@openssh.com":
		return string(pk.EdPub) == string(other.EdPub) && pk.App == other.App
	default: // ecdsa variants
		return pk.Curve == other.Curve && string(pk.Q) == string(other.Q) && pk.App == other.App
	}
}

// Verify signature. signedData as per userauth. sigBlob is SSH signature blob contents.
func (pk *PubKey) verify(sigAlgo string, sigBlob []byte, signedData []byte) bool {
	r := newReader(sigBlob)
	sigAlgInBlob := r.str()
	sig := r.strBytes()
	if r.err != nil {
		return false
	}
	// sigAlgo parameter is algorithm from request; blob's algo should match it (except hostbound)
	_ = sigAlgo
	switch pk.Type {
	case "ssh-rsa":
		algo := sigAlgInBlob
		var h crypto.Hash
		var digest []byte
		switch algo {
		case "rsa-sha2-256":
			d := sha256.Sum256(signedData)
			digest = d[:]
			h = crypto.SHA256
		case "rsa-sha2-512":
			d := sha512.Sum512(signedData)
			digest = d[:]
			h = crypto.SHA512
		case "ssh-rsa":
			d := shaSum1(signedData)
			digest = d[:]
			h = crypto.SHA1
		default:
			return false
		}
		pub := &rsa.PublicKey{N: pk.N, E: int(pk.E.Int64())}
		// E may not fit int if huge, but standard keys ok
		if pk.E.BitLen() > 31 {
			// manual verification
			return rsaVerifyRaw(pub, h, digest, sig)
		}
		return rsa.VerifyPKCS1v15(pub, h, digest, sig) == nil
	case "ssh-ed25519":
		if sigAlgInBlob != "ssh-ed25519" || len(sig) != 64 {
			return false
		}
		return ed25519.Verify(ed25519.PublicKey(pk.EdPub), signedData, sig)
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		if sigAlgInBlob != pk.Type {
			return false
		}
		info, ok := ecdsaCurves[pk.Curve]
		if !ok {
			return false
		}
		sr := newReader(sig)
		rv := sr.mpint()
		sv := sr.mpint()
		if sr.err != nil {
			return false
		}
		var digest []byte
		switch pk.Curve {
		case "nistp256":
			d := sha256.Sum256(signedData)
			digest = d[:]
		case "nistp384":
			d := sha512.Sum384(signedData)
			digest = d[:]
		case "nistp521":
			d := sha512.Sum512(signedData)
			digest = d[:]
		}
		x, y := unmarshalCurve(info.curve, pk.Q)
		if x == nil {
			return false
		}
		pub := &ecdsa.PublicKey{Curve: info.curve, X: x, Y: y}
		return ecdsa.Verify(pub, digest, rv, sv)
	case "sk-ssh-ed25519@openssh.com":
		return pk.verifySKEd25519(sigAlgInBlob, sig, signedData)
	case "sk-ecdsa-sha2-nistp256@openssh.com":
		return pk.verifySKEcdsa(sigAlgInBlob, sig, signedData)
	}
	return false
}

func rsaVerifyRaw(pub *rsa.PublicKey, h crypto.Hash, digest, sig []byte) bool {
	// Use stdlib with manually constructed key if E fits; fallback manual pow
	k := (pub.N.BitLen() + 7) / 8
	if len(sig) != k {
		return false
	}
	m := new(big.Int).SetBytes(sig)
	if m.Cmp(pub.N) >= 0 {
		return false
	}
	e := big.NewInt(pub.ExtendedE())
	// fallback, never reached in practice
	_ = e
	return false
}

// SK verification per RFC / OpenSSH PROTOCOL.u2f
// signature blob contents for sk: string sig (ed25519), byte flags, uint32 counter
func (pk *PubKey) verifySKEd25519(sigAlg string, sig []byte, signedData []byte) bool {
	if sigAlg != "sk-ssh-ed25519@openssh.com" {
		return false
	}
	r := newReader(sig)
	rawSig := r.strBytes() // may be raw if parsing fails, handle below
	var flags byte
	var counter uint32
	var innerSig []byte
	if r.err == nil && len(rawSig) >= 64 {
		innerSig = rawSig[:64]
		if r.remaining() >= 5 {
			flags = r.byte()
			counter = r.uint32()
		}
	} else {
		// sig field itself is the blob: SSH signature for sk is a string containing:
		// string signature, byte flags, uint32 counter ... Actually overall sig blob already
		// parsed: r.str() gave alg, r.strBytes() gave the whole sk sig structure as one string.
		// So this branch not needed
		return false
	}
	_ = counter
	// signed data for SK: SHA512( app || flags || counter || SHA256(message) )
	// where app is the application string from key blob ("ssh:")
	appHash := sha256.Sum256([]byte(pk.App))
	_ = appHash
	msgHash := sha256.Sum256(signedData)
	h := sha512.New()
	// application hashed? In PROTOCOL.u2f, the "application" parameter is SHA256(app) passed to authenticator,
	// and authenticator signs over appHash || flags || counter || msgHash
	appParam := sha256.Sum256([]byte(pk.App))
	h.Write(appParam[:])
	h.Write([]byte{flags})
	var cb [4]byte
	cb[0] = byte(counter >> 24)
	cb[1] = byte(counter >> 16)
	cb[2] = byte(counter >> 8)
	cb[3] = byte(counter)
	h.Write(cb[:])
	h.Write(msgHash[:])
	digest := h.Sum(nil)
	// authenticator signs the hash? WebAuthn-style: ed25519 signature is over the constructed data above (not pre-hashed?)
	// In OpenSSH sk ed25519, verification is ed25519.Verify(pub, dataToSign, sig) where dataToSign is the above  (appHash||flags||counter||hash) ??? It is not additionally hashed with SHA512 inside ed25519 (Ed25519 does its own)
	// The 'digest' computed as sha512 is used by ecdsa sk; for ed25519, use the raw concatenation
	dataToSign := append([]byte{}, appParam[:]...)
	dataToSign = append(dataToSign, flags)
	dataToSign = append(dataToSign, cb[:]...)
	dataToSign = append(dataToSign, msgHash[:]...)
	_ = digest
	return ed25519.Verify(ed25519.PublicKey(pk.EdPub), dataToSign, innerSig)
}

func (pk *PubKey) verifySKEcdsa(sigAlg string, sig []byte, signedData []byte) bool {
	// similar but ECDSA signature is (r,s) mpints inside a string, followed by flags/counter
	// Parse sig as: string ecSig, byte flags, uint32 counter
	r := newReader(sig)
	ecSig := r.strBytes()
	if r.err != nil || r.remaining() < 5 {
		return false
	}
	flags := r.byte()
	counter := r.uint32()
	sr := newReader(ecSig)
	rv := sr.mpint()
	sv := sr.mpint()
	if sr.err != nil {
		return false
	}
	appParam := sha256.Sum256([]byte(pk.App))
	msgHash := sha256.Sum256(signedData)
	h := sha512.New()
	h.Write(appParam[:])
	h.Write([]byte{flags})
	var cb [4]byte
	cb[0] = byte(counter >> 24)
	cb[1] = byte(counter >> 16)
	cb[2] = byte(counter >> 8)
	cb[3] = byte(counter)
	h.Write(cb[:])
	h.Write(msgHash[:])
	digest := h.Sum(nil)
	// ECDSA P256 verifies with SHA256 of digest? In OpenSSH, the data is hashed with the curve hash over digest
	d2 := sha256.Sum256(digest)
	info := ecdsaCurves["nistp256"]
	x, y := unmarshalCurve(info.curve, pk.Q)
	if x == nil {
		return false
	}
	pub := &ecdsa.PublicKey{Curve: info.curve, X: x, Y: y}
	return ecdsa.Verify(pub, d2[:], rv, sv)
}

// ----- authorized_keys ------

type AuthKeyOptions struct {
	NoPty bool
	NoPortForwarding bool
	NoAgentForwarding bool
	NoX11Forwarding bool
	NoTouchRequired bool
	Restrict bool
	ForcedCommand string
	HasForcedCommand bool
	PermitOpen []string // host:port strings
}

func (sess *session) authorizedKeysPath() string {
	if sess.opts.HasAuthKeysDir {
		return filepath.Join(sess.opts.AuthKeysDir, "authorized_keys")
	}
	return filepath.Join(sess.pw.Home, ".ssh", "authorized_keys")
}

// check directory permissions for authorized_keys path components.
// Returns false (and logs) if a component fails checks.
func checkAuthorizedPath(path string, user *PasswdEntry) bool {
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}
	dir := filepath.Dir(abs)
	// Build prefixes from root down to dir
	var prefixes []string
	cur := string(filepath.Separator)
	prefixes = append(prefixes, cur)
	parts := strings.Split(strings.Trim(dir, "/"), "/")
	if !(len(parts) == 1 && parts[0] == "") {
		for _, p := range parts {
			if p == "" {
				continue
			}
			cur = filepath.Join(cur, p)
			prefixes = append(prefixes, cur)
		}
	}
	for _, prefix := range prefixes {
		info, err := os.Stat(prefix)
		if err != nil {
			return false // missing component - file open will fail silently
		}
		st, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			continue
		}
		if st.Uid != uint32(user.UID) && st.Uid != 0 {
			logMsg("%s must be owned by user or root, and not writable by group or others", prefix)
			return false
		}
		if info.Mode().Perm()&0o022 != 0 {
			logMsg("%s must be owned by user or root, and not writable by group or others", prefix)
			return false
		}
	}
	// file ownership check (mode ignored based on observation)
	if info, err := os.Stat(abs); err == nil {
		if st, ok := info.Sys().(*syscall.Stat_t); ok {
			if st.Uid != uint32(user.UID) && st.Uid != 0 {
				logMsg("%s must be owned by user or root, and not writable by group or others", abs)
				return false
			}
		}
	}
	return true
}

// find matching authorized key. Parses file each call (like dropbear).
// Returns (matched key options, pubkeyInfo, found)
func (sess *session) checkAuthorizedKey(offered *PubKey) (*AuthKeyOptions, string, bool) {
	if sess.pw == nil {
		return nil, "", false
	}
	path := sess.authorizedKeysPath()
	if !checkAuthorizedPath(path, sess.pw) {
		return nil, "", false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, "", false
	}
	lines := strings.Split(string(data), "\n")
	for idx, rawLine := range lines {
		lineNo := idx + 1
		line := strings.TrimSuffix(rawLine, "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		// parse line
		opts, key, info, badOpt, ok := parseAuthorizedLine(line, path, lineNo)
		if badOpt {
			logMsg("Bad public key options at %s:%d", path, lineNo)
			continue
		}
		if !ok {
			continue
		}
		if key.equal(offered) {
			return opts, info, true
		}
	}
	return nil, "", false
}

// parse one authorized_keys line.
// Returns options, key, pubkeyInfo, badOptions flag, ok flag
func parseAuthorizedLine(line, path string, lineNo int) (*AuthKeyOptions, *PubKey, string, bool, bool) {
	opts := &AuthKeyOptions{}
	rest := line
	// Determine if line begins with a known key type; if not, first field is options
	// We need to find key type token. Options have no spaces (except quoted).
	firstSpace := strings.IndexAny(rest, " \t")
	var firstToken string
	if firstSpace >= 0 {
		firstToken = rest[:firstSpace]
	} else {
		firstToken = rest
	}
	knownTypes := map[string]bool{
		"ssh-rsa": true, "ssh-ed25519": true, "ssh-dss": true,
		"ecdsa-sha2-nistp256": true, "ecdsa-sha2-nistp384": true, "ecdsa-sha2-nistp521": true,
		"sk-ssh-ed25519@openssh.com": true, "sk-ecdsa-sha2-nistp256@openssh.com": true,
	}
	if !knownTypes[firstToken] {
		// options field: it ends at first unquoted whitespace
		optStr, remaining, ok := splitOptionsField(rest)
		if !ok {
			return nil, nil, "", true, false
		}
		// parse options
		if !parseOptions(optStr, opts) {
			return nil, nil, "", true, false
		}
		rest = remaining
	}
	// now rest should be: keytype SP base64 [SP comment]
	// find keytype
	sp := strings.IndexAny(rest, " \t")
	if sp < 0 {
		return nil, nil, "", false, false
	}
	keyType := rest[:sp]
	if !knownTypes[keyType] {
		return nil, nil, "", false, false
	}
	rest2 := rest[sp+1:]
	// base64 token up to space/tab
	sp2 := strings.IndexAny(rest2, " \t")
	var b64 string
	var after string
	var afterSep byte
	if sp2 < 0 {
		b64 = rest2
		after = ""
	} else {
		b64 = rest2[:sp2]
		afterSep = rest2[sp2]
		after = rest2[sp2:] // includes separator
	}
	blob, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		// try without padding
		blob, err = base64.RawStdEncoding.DecodeString(b64)
		if err != nil {
			return nil, nil, "", false, false
		}
