	if key.Type != keyType {
		return nil, nil, "", false, false
	}
	// SSH_PUBKEYINFO: only if after starts with exactly one space (0x20)
	info := ""
	if afterSep == ' ' && len(after) >= 1 {
		// after[0] is the separator char
		cand := after[1:]
		// if cand starts with space/tab, invalid (double space case)
		if len(cand) > 0 && cand[0] != ' ' && cand[0] != '\t' {
			// token up to next space
			token := cand
			if idx := strings.Index(cand, " "); idx >= 0 {
				token = cand[:idx]
			}
			if pubkeyInfoValid(token) {
				info = token
			}
		}
	}
	return opts, key, info, false, true
}

func pubkeyInfoValid(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range []byte(s) {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '@' || c == '.' || c == '_' || c == '-' || c == '+' || c == ',' {
			continue
		}
		return false
	}
	return true
}

// split options field: options are comma separated, no unquoted spaces; quoted strings may contain spaces
// returns option string, rest of line (starting at key type)
func splitOptionsField(line string) (string, string, bool) {
	inQuote := false
	escaped := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if escaped {
			escaped = false
			continue
		}
		if c == '\\' && inQuote {
			escaped = true
			continue
		}
		if c == '"' {
			inQuote = !inQuote
			continue
		}
		if !inQuote && (c == ' ' || c == '\t') {
			// rest trimmed of that single separator? dropbear likely skips whitespace
			rest := strings.TrimLeft(line[i+1:], " \t")
			// But need preserve separator info for pubkey info? caller handles after key
			return line[:i], rest, true
		}
	}
	return "", "", false
}

func parseOptions(optStr string, opts *AuthKeyOptions) bool {
	// split by commas not inside quotes
	var tokens []string
	var cur strings.Builder
	inQuote := false
	escaped := false
	for i := 0; i < len(optStr); i++ {
		c := optStr[i]
		if escaped {
			cur.WriteByte(c)
			escaped = false
			continue
		}
		if c == '\\' && inQuote {
			// keep escaped char for later unquoting; write marker
			escaped = true
			continue
		}
		if c == '"' {
			inQuote = !inQuote
			cur.WriteByte(c)
			continue
		}
		if c == ',' && !inQuote {
			tokens = append(tokens, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	if inQuote {
		return false
	}
	tokens = append(tokens, cur.String())
	for _, tok := range tokens {
		switch {
		case tok == "no-pty":
			logMsg("Pty allocation disabled.")
			opts.NoPty = true
		case tok == "no-port-forwarding":
			logMsg("Port forwarding disabled.")
			opts.NoPortForwarding = true
		case tok == "no-agent-forwarding":
			logMsg("Agent forwarding disabled.")
			opts.NoAgentForwarding = true
		case tok == "no-X11-forwarding":
			opts.NoX11Forwarding = true
		case tok == "no-touch-required":
			logMsg("No user presence check required for U2F/FIDO key.")
			opts.NoTouchRequired = true
		case tok == "restrict":
			logMsg("Restrict option set")
			opts.Restrict = true
			opts.NoPty = true
			opts.NoPortForwarding = true
			opts.NoAgentForwarding = true
			opts.NoX11Forwarding = true
		case strings.HasPrefix(tok, "command="):
			v, ok := unquoteOptionValue(tok[len("command="):])
			if !ok {
				return false
			}
			opts.ForcedCommand = v
			opts.HasForcedCommand = true
		case strings.HasPrefix(tok, "permitopen="):
			v, ok := unquoteOptionValue(tok[len("permitopen="):])
			if !ok {
				return false
			}
			opts.PermitOpen = append(opts.PermitOpen, v)
		case strings.HasPrefix(tok, "permitlisten="):
			// observed? treat like permitopen variant - mark bad if not supported later
			// Dropbear likely doesn't support; return false
			return false
		default:
			return false
		}
	}
	return true
}

func unquoteOptionValue(s string) (string, bool) {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return s[1:len(s)-1], true
	}
	// unquoted values: dropbear may accept some; command requires quotes, permitopen in openssh requires quotes
	// Accept unquoted as well if no spaces/commas (already tokenized)
	if s == "" {
		return "", false
	}
	return s, true
}
