	E, N *big.Int
	// ED
	EdPub []byte
	// ECDSA
	Curve string
	Q     []byte
	// SK
	App string
	IsSK bool
}

func parsePubKeyBlob(blob []byte) (*PubKey, error) {
	r := newReader(blob)
	typ := r.str()
	pk := &PubKey{Type: typ, Blob: append([]byte{}, blob...)}
	switch typ {
	case "ssh-rsa":
		pk.E = r.mpint()
		pk.N = r.mpint()
	case "ssh-ed25519":
		pk.EdPub = r.strBytes()
		if len(pk.EdPub) != 32 {
			return nil, fmt.Errorf("bad ed pub")
		}
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		pk.Curve = r.str()
		pk.Q = r.strBytes()
	case "sk-ssh-ed25519@openssh.com":
		pk.IsSK = true
		pk.EdPub = r.strBytes()
		pk.App = r.str()
	case "sk-ecdsa-sha2-nistp256@openssh.com":
		pk.IsSK = true
		pk.Curve = r.str()
		pk.Q = r.strBytes()
		pk.App = r.str()
	default:
		return nil, fmt.Errorf("unsupported key type %s", typ)
	}
	if r.err != nil {
		return nil, r.err
	}
	return pk, nil
}

func (pk *PubKey) fingerprint() string {
	return fingerprint(pk.Blob)
}

func (pk *PubKey) equal(other *PubKey) bool {
	if pk.Type != other.Type {
		return false
	}
	switch pk.Type {
	case "ssh-rsa":
		return pk.E.Cmp(other.E) == 0 && pk.N.Cmp(other.N) == 0
	case "ssh-ed25519", "sk-ssh-ed25519@openssh.com":
		return string(pk.EdPub) == string(other.EdPub) && pk.App == other.App
	default: // ecdsa variants
		return pk.Curve == other.Curve && string(pk.Q) == string(other.Q) && pk.App == other.App
	}
}

// Verify signature. signedData as per userauth. sigBlob is SSH signature blob contents.
func (pk *PubKey) verify(sigAlgo string, sigBlob []byte, signedData []byte) bool {
	r := newReader(sigBlob)
	sigAlgInBlob := r.str()
	sig := r.strBytes()
	if r.err != nil {
		return false
	}
	// sigAlgo parameter is algorithm from request; blob's algo should match it (except hostbound)
	_ = sigAlgo
	switch pk.Type {
	case "ssh-rsa":
		algo := sigAlgInBlob
		var h crypto.Hash
		var digest []byte
		switch algo {
		case "rsa-sha2-256":
			d := sha256.Sum256(signedData)
			digest = d[:]
			h = crypto.SHA256
		case "rsa-sha2-512":
			d := sha512.Sum512(signedData)
			digest = d[:]
			h = crypto.SHA512
		case "ssh-rsa":
			d := shaSum1(signedData)
			digest = d[:]
			h = crypto.SHA1
