		switch pk.Curve {
		case "nistp256":
			d := sha256.Sum256(signedData)
			digest = d[:]
		case "nistp384":
			d := sha512.Sum384(signedData)
			digest = d[:]
		case "nistp521":
			d := sha512.Sum512(signedData)
			digest = d[:]
		}
		x, y := unmarshalCurve(info.curve, pk.Q)
		if x == nil {
