// check directory permissions for authorized_keys path components.
// Returns false (and logs) if a component fails checks.
func checkAuthorizedPath(path string, user *PasswdEntry) bool {
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}
	dir := filepath.Dir(abs)
	// Build prefixes from root down to dir
	var prefixes []string
	cur := string(filepath.Separator)
	prefixes = append(prefixes, cur)
	parts := strings.Split(strings.Trim(dir, "/"), "/")
	if !(len(parts) == 1 && parts[0] == "") {
		for _, p := range parts {
			if p == "" {
