		pk.EdPub = r.strBytes()
		pk.App = r.str()
	case "sk-ecdsa-sha2-nistp256@openssh.com":
		pk.IsSK = true
		pk.Curve = r.str()
		pk.Q = r.strBytes()
		pk.App = r.str()
	default:
		return nil, fmt.Errorf("unsupported key type %s", typ)
