	var flags byte
	var counter uint32
	var innerSig []byte
	if r.err == nil && len(rawSig) >= 64 {
		innerSig = rawSig[:64]
		if r.remaining() >= 5 {
			flags = r.byte()
			counter = r.uint32()
		}
	} else {
		// sig field itself is the blob: SSH signature for sk is a string containing:
		// string signature, byte flags, uint32 counter ... Actually overall sig blob already
		// parsed: r.str() gave alg, r.strBytes() gave the whole sk sig structure as one string.
		// So this branch not needed
		return false
