	// and authenticator signs over appHash || flags || counter || msgHash
	appParam := sha256.Sum256([]byte(pk.App))
	h.Write(appParam[:])
	h.Write([]byte{flags})
	var cb [4]byte
	cb[0] = byte(counter >> 24)
	cb[1] = byte(counter >> 16)
	cb[2] = byte(counter >> 8)
	cb[3] = byte(counter)
	h.Write(cb[:])
	h.Write(msgHash[:])
