	x, y := unmarshalCurve(info.curve, pk.Q)
	if x == nil {
		return false
	}
	pub := &ecdsa.PublicKey{Curve: info.curve, X: x, Y: y}
	return ecdsa.Verify(pub, d2[:], rv, sv)
}

// ----- authorized_keys ------

type AuthKeyOptions struct {
	NoPty bool
	NoPortForwarding bool
	NoAgentForwarding bool
	NoX11Forwarding bool
	NoTouchRequired bool
	Restrict bool
	ForcedCommand string
	HasForcedCommand bool
	PermitOpen []string // host:port strings
}

func (sess *session) authorizedKeysPath() string {
	if sess.opts.HasAuthKeysDir {
		return filepath.Join(sess.opts.AuthKeysDir, "authorized_keys")
	}
	return filepath.Join(sess.pw.Home, ".ssh", "authorized_keys")
}

// check directory permissions for authorized_keys path components.
// Returns false (and logs) if a component fails checks.
func checkAuthorizedPath(path string, user *PasswdEntry) bool {
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}
	dir := filepath.Dir(abs)
	// Build prefixes from root down to dir
	var prefixes []string
	cur := string(filepath.Separator)
	prefixes = append(prefixes, cur)
	parts := strings.Split(strings.Trim(dir, "/"), "/")
	if !(len(parts) == 1 && parts[0] == "") {
		for _, p := range parts {
			if p == "" {
				continue
			}
			cur = filepath.Join(cur, p)
			prefixes = append(prefixes, cur)
		}
	}
	for _, prefix := range prefixes {
		info, err := os.Stat(prefix)
		if err != nil {
			return false // missing component - file open will fail silently
		}
		st, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			continue
		}
		if st.Uid != uint32(user.UID) && st.Uid != 0 {
			logMsg("%s must be owned by user or root, and not writable by group or others", prefix)
			return false
		}
		if info.Mode().Perm()&0o022 != 0 {
			logMsg("%s must be owned by user or root, and not writable by group or others", prefix)
			return false
		}
	}
	// file ownership check (mode ignored based on observation)
	if info, err := os.Stat(abs); err == nil {
		if st, ok := info.Sys().(*syscall.Stat_t); ok {
			if st.Uid != uint32(user.UID) && st.Uid != 0 {
				logMsg("%s must be owned by user or root, and not writable by group or others", abs)
				return false
			}
		}
	}
	return true
}

// find matching authorized key. Parses file each call (like dropbear).
// Returns (matched key options, pubkeyInfo, found)
func (sess *session) checkAuthorizedKey(offered *PubKey) (*AuthKeyOptions, string, bool) {
	if sess.pw == nil {
		return nil, "", false
	}
	path := sess.authorizedKeysPath()
	if !checkAuthorizedPath(path, sess.pw) {
		return nil, "", false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, "", false
	}
	lines := strings.Split(string(data), "\n")
	for idx, rawLine := range lines {
		lineNo := idx + 1
		line := strings.TrimSuffix(rawLine, "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		// parse line
		opts, key, info, badOpt, ok := parseAuthorizedLine(line, path, lineNo)
		if badOpt {
			logMsg("Bad public key options at %s:%d", path, lineNo)
			continue
		}
		if !ok {
			continue
		}
		if key.equal(offered) {
			return opts, info, true
		}
	}
	return nil, "", false
}

// parse one authorized_keys line.
// Returns options, key, pubkeyInfo, badOptions flag, ok flag
func parseAuthorizedLine(line, path string, lineNo int) (*AuthKeyOptions, *PubKey, string, bool, bool) {
	opts := &AuthKeyOptions{}
	rest := line
	// Determine if line begins with a known key type; if not, first field is options
	// We need to find key type token. Options have no spaces (except quoted).
	firstSpace := strings.IndexAny(rest, " \t")
	var firstToken string
	if firstSpace >= 0 {
		firstToken = rest[:firstSpace]
	} else {
		firstToken = rest
	}
	knownTypes := map[string]bool{
		"ssh-rsa": true, "ssh-ed25519": true, "ssh-dss": true,
		"ecdsa-sha2-nistp256": true, "ecdsa-sha2-nistp384": true, "ecdsa-sha2-nistp521": true,
		"sk-ssh-ed25519@openssh.com": true, "sk-ecdsa-sha2-nistp256@openssh.com": true,
	}
	if !knownTypes[firstToken] {
		// options field: it ends at first unquoted whitespace
		optStr, remaining, ok := splitOptionsField(rest)
		if !ok {
			return nil, nil, "", true, false
		}
		// parse options
		if !parseOptions(optStr, opts) {
			return nil, nil, "", true, false
		}
		rest = remaining
	}
	// now rest should be: keytype SP base64 [SP comment]
	// find keytype
	sp := strings.IndexAny(rest, " \t")
	if sp < 0 {
		return nil, nil, "", false, false
	}
	keyType := rest[:sp]
	if !knownTypes[keyType] {
		return nil, nil, "", false, false
	}
	rest2 := rest[sp+1:]
	// base64 token up to space/tab
	sp2 := strings.IndexAny(rest2, " \t")
	var b64 string
	var after string
	var afterSep byte
	if sp2 < 0 {
		b64 = rest2
		after = ""
	} else {
		b64 = rest2[:sp2]
		afterSep = rest2[sp2]
		after = rest2[sp2:] // includes separator
	}
	blob, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		// try without padding
		blob, err = base64.RawStdEncoding.DecodeString(b64)
		if err != nil {
			return nil, nil, "", false, false
		}
	}
	key, err := parsePubKeyBlob(blob)
	if err != nil {
		return nil, nil, "", false, false
	}
	if key.Type != keyType {
		return nil, nil, "", false, false
	}
	// SSH_PUBKEYINFO: only if after starts with exactly one space (0x20)
	info := ""
	if afterSep == ' ' && len(after) >= 1 {
		// after[0] is the separator char
		cand := after[1:]
		// if cand starts with space/tab, invalid (double space case)
		if len(cand) > 0 && cand[0] != ' ' && cand[0] != '\t' {
			// token up to next space
			token := cand
			if idx := strings.Index(cand, " "); idx >= 0 {
				token = cand[:idx]
			}
			if pubkeyInfoValid(token) {
				info = token
			}
		}
	}
	return opts, key, info, false, true
}

func pubkeyInfoValid(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range []byte(s) {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '@' || c == '.' || c == '_' || c == '-' || c == '+' || c == ',' {
			continue
		}
		return false
	}
	return true
}

// split options field: options are comma separated, no unquoted spaces; quoted strings may contain spaces
// returns option string, rest of line (starting at key type)
func splitOptionsField(line string) (string, string, bool) {
	inQuote := false
	escaped := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if escaped {
			escaped = false
			continue
		}
		if c == '\\' && inQuote {
			escaped = true
			continue
		}
		if c == '"' {
			inQuote = !inQuote
			continue
		}
		if !inQuote && (c == ' ' || c == '\t') {
			// rest trimmed of that single separator? dropbear likely skips whitespace
			rest := strings.TrimLeft(line[i+1:], " \t")
			// But need preserve separator info for pubkey info? caller handles after key
			return line[:i], rest, true
		}
	}
	return "", "", false
}

func parseOptions(optStr string, opts *AuthKeyOptions) bool {
	// split by commas not inside quotes
	var tokens []string
	var cur strings.Builder
	inQuote := false
	escaped := false
	for i := 0; i < len(optStr); i++ {
		c := optStr[i]
		if escaped {
			cur.WriteByte(c)
			escaped = false
			continue
		}
		if c == '\\' && inQuote {
			// keep escaped char for later unquoting; write marker
			escaped = true
			continue
		}
		if c == '"' {
			inQuote = !inQuote
			cur.WriteByte(c)
			continue
		}
		if c == ',' && !inQuote {
			tokens = append(tokens, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	if inQuote {
		return false
	}
	tokens = append(tokens, cur.String())
	for _, tok := range tokens {
		switch {
		case tok == "no-pty":
			logMsg("Pty allocation disabled.")
			opts.NoPty = true
		case tok == "no-port-forwarding":
			logMsg("Port forwarding disabled.")
			opts.NoPortForwarding = true
		case tok == "no-agent-forwarding":
			logMsg("Agent forwarding disabled.")
			opts.NoAgentForwarding = true
		case tok == "no-X11-forwarding":
			opts.NoX11Forwarding = true
		case tok == "no-touch-required":
			logMsg("No user presence check required for U2F/FIDO key.")
			opts.NoTouchRequired = true
		case tok == "restrict":
			logMsg("Restrict option set")
			opts.Restrict = true
			opts.NoPty = true
			opts.NoPortForwarding = true
			opts.NoAgentForwarding = true
			opts.NoX11Forwarding = true
		case strings.HasPrefix(tok, "command="):
			v, ok := unquoteOptionValue(tok[len("command="):])
			if !ok {
				return false
			}
			opts.ForcedCommand = v
			opts.HasForcedCommand = true
		case strings.HasPrefix(tok, "permitopen="):
			v, ok := unquoteOptionValue(tok[len("permitopen="):])
			if !ok {
				return false
			}
			opts.PermitOpen = append(opts.PermitOpen, v)
		case strings.HasPrefix(tok, "permitlisten="):
			// observed? treat like permitopen variant - mark bad if not supported later
			// Dropbear likely doesn't support; return false
			return false
		default:
			return false
		}
	}
	return true
}

func unquoteOptionValue(s string) (string, bool) {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return s[1:len(s)-1], true
	}
	// unquoted values: dropbear may accept some; command requires quotes, permitopen in openssh requires quotes
	// Accept unquoted as well if no spaces/commas (already tokenized)
	if s == "" {
		return "", false
	}
	return s, true
}
EOF
"}

