{"command":"cat > server.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"io"
	"net"
	"os"
	"strings"
	"sync"
	"time"
)

type session struct {
	opts *Options
	conn net.Conn
	trans *transport

	remoteAddr string // "127.0.0.1:1234" form used in logs (ip:port with brackets for v6 as net)
	remoteIP string
	remotePort int
	localIP string
	localPort int

	user string
	pw *PasswdEntry
	userValid bool
	userChecked bool
	checkedUser string

	failures int
	authDone bool
	pubkeyDone bool
	passwordDone bool
	bannerSent bool

	pubkeyOpts *AuthKeyOptions
	pubkeyInfo string
	usedPubkey bool

	channelsMu sync.Mutex
	channels map[uint32]*channel
	nextChannelID uint32

	forwardsMu sync.Mutex
	forwards map[string]*forwardListener

	agentListener net.Listener
	agentPath string
	agentDir string

	lastActivity time.Time
	started time.Time
	exitReason string

	motdSent map[uint32]bool
}

type forwardListener struct {
	ln net.Listener
	bindAddr string
	port uint32
}

func (sess *session) remoteLogAddr() string {
	// format like 127.0.0.1:1234 (for IPv6, net Addr.String gives [::1]:port)
	if sess.conn != nil && sess.conn.RemoteAddr() != nil {
		return sess.conn.RemoteAddr().String()
	}
	return sess.remoteAddr
}

// handleConnection runs the full SSH session for one connection.
// It is executed in a dedicated child process (or inetd mode).
func handleConnection(conn net.Conn, opts *Options) {
	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(*fatalError); ok {
				// log exit accordingly - need sess context; handled via global current session
				handleFatal(fe.msg)
				os.Exit(1)
			}
			// unexpected panic: log and exit 1?
			// re-panic for debugging via env
			if os.Getenv("DBDEBUG_PANIC") != "" {
				panic(r)
			}
			handleFatal(fmt.Sprintf("%v", r))
			os.Exit(1)
		}
	}()
	runSession(conn, opts)
}

// the currently active session for fatal handling (one per process)
var curSession *session

func handleFatal(msg string) {
	sess := curSession
	if sess == nil {
		logMsg("Early exit: %s", msg)
		return
	}
	sess.logExit(msg)
}

func (sess *session) logExit(reason string) {
	if sess.authDone {
		logMsg("Exit (%s) from <%s>: %s", sess.user, sess.remoteLogAddr(), reason)
	} else {
		if sess.pw != nil {
			logMsg("Exit before auth from <%s>: (user '%s', %d fails): %s", sess.remoteLogAddr(), sess.user, sess.failures, reason)
		} else {
			logMsg("Exit before auth from <%s>: %s", sess.remoteLogAddr(), reason)
		}
	}
}

func runSession(conn net.Conn, opts *Options) {
	sess := &session{
		opts: opts,
		conn: conn,
		channels: make(map[uint32]*channel),
		forwards: make(map[string]*forwardListener),
		started: time.Now(),
		lastActivity: time.Now(),
		motdSent: make(map[uint32]bool),
	}
	curSession = sess
	if ra, ok := conn.RemoteAddr().(*net.TCPAddr); ok {
		sess.remoteIP = ra.IP.String()
		sess.remotePort = ra.Port
	}
	if la, ok := conn.LocalAddr().(*net.TCPAddr); ok {
		sess.localIP = la.IP.String()
		sess.localPort = la.Port
	}
	sess.remoteAddr = conn.RemoteAddr().String()

	logMsg("Child connection from %s", sess.remoteLogAddr())

	// QoS
	if !opts.DisableQoS {
		setQoS(conn, false)
	}

	br := bufio.NewReaderSize(conn, 4096)
	trans := &transport{conn: conn, br: br, sess: sess}
	sess.trans = trans

	// send banner and KEXINIT immediately
	kexPayload := sess.makeKexInit()
	trans.serverKexPayload = kexPayload
	if _, err := conn.Write([]byte(serverVersion + "\r\n")); err != nil {
		sess.finishExit("Exited normally")
		return
	}
	// write KEXINIT packet (no encryption yet)
	if err := trans.writePacket(kexPayload); err != nil {
		sess.finishExit(exitReasonFromErr(err))
		return
	}

	// read client version
	clientVer, err := readClientVersion(br)
	if err != nil {
		if verr, ok := err.(*versionError); ok {
			sess.finishExit(fmt.Sprintf("Incompatible remote version '%s'", verr.version))
			return
		}
		sess.finishExit(exitReasonFromErr(err))
		return
	}
	trans.clientVersion = clientVer

	// read client KEXINIT
	firstPacket, err := trans.readPacket()
	if err != nil {
		sess.finishExit(exitReasonFromErr(err))
		return
	}
	if len(firstPacket) == 0 || firstPacket[0] != msgKexInit {
		// dropbear would treat as kex error?
		sess.finishExit("Exited normally")
		return
	}
	trans.clientKexPayload = firstPacket
	if err := trans.handleKex(firstPacket); err != nil {
		sess.finishExit(exitReasonFromErr(err))
		return
	}

	// service request + auth
	if !sess.doServiceAndAuth() {
		return
	}

	// after auth, activate delayed compression
	if trans.compAlgo == "zlib@openssh.com" {
		trans.compActive = true
		trans.compWriter = nil
	}

	// main loop
	sess.mainLoop()
}

func (sess *session) finishExit(reason string) {
	if reason == "" {
		reason = "Exited normally"
	}
	sess.logExit(reason)
	if sess.conn != nil {
		sess.conn.Close()
	}
	// cleanup forwards, agent, channels processes
	sess.cleanup()
	os.Exit(0)
}

func exitReasonFromErr(err error) string {
	if err == nil {
		return "Exited normally"
	}
	if err == io.EOF || err == io.ErrUnexpectedEOF {
		return "Exited normally"
	}
	msg := err.Error()
	if strings.Contains(msg, "connection reset by peer") {
		return "Error reading: Connection reset by peer"
	}
	if strings.Contains(msg, "broken pipe") {
		return "Error writing: Broken pipe" // approximate; write errors handled elsewhere
	}
	return "Exited normally"
}

type versionError struct{ version string }
func (e *versionError) Error() string { return "incompatible version " + e.version }

func readClientVersion(br *bufio.Reader) (string, error) {
	// read lines until a line starting with SSH-
	for {
		line, err := readVersionLine(br)
		if err != nil {
			return "", err
		}
		// line without trailing CRLF
		if strings.HasPrefix(line, "SSH-") {
			if strings.HasPrefix(line, "SSH-2.0-") || strings.HasPrefix(line, "SSH-1.99-") {
				return line, nil
			}
			return "", &versionError{version: line}
		}
		// ignore other lines
	}
}

// read one line limited to 256 bytes; returns content without CRLF/LF.
// If line exceeds limit, returns first chunk as line (rest remains buffered)
func readVersionLine(br *bufio.Reader) (string, error) {
	var buf []byte
	for {
		b, err := br.ReadByte()
		if err != nil {
			if len(buf) > 0 {
				break
			}
			return "", err
		}
		if b == '\n' {
			break
		}
		buf = append(buf, b)
		if len(buf) >= 256 {
			break
		}
	}
	// strip trailing \r
	s := strings.TrimSuffix(string(buf), "\r")
	return s, nil
}

func (sess *session) doServiceAndAuth() bool {
	// wait for service request
	for {
		p, err := sess.trans.readPacket()
		if err != nil {
			sess.finishExit(exitReasonFromErr(err))
			return false
		}
		if len(p) == 0 {
			continue
		}
		switch p[0] {
		case msgKexInit:
			if err := sess.trans.handleKex(p); err != nil {
				sess.finishExit(exitReasonFromErr(err))
				return false
			}
			continue
		case msgServiceRequest:
			r := newReader(p)
			r.byte()
			svc := r.str()
			if svc != "ssh-userauth" {
				// dropbear: unknown service -> disconnect?
				sess.finishExit("Exited normally")
				return false
			}
			w := &writer{}
			w.byte(msgServiceAccept)
			w.str(svc)
			if err := sess.trans.writePacket(w.Bytes()); err != nil {
				sess.finishExit(exitReasonFromErr(err))
				return false
			}
			// proceed to auth
			return sess.doAuth()
		case msgIgnore, msgDebug, msgExtInfo, msgUnimplemented:
			continue
		case msgDisconnect:
			sess.finishExit("Disconnect received")
			return false
		default:
			continue
		}
	}
}
EOF
"}

