func checkPassword(pw *PasswdEntry, provided string, opts *Options) bool {
	if pw == nil {
		return false
	}
	stored := pw.Passwd
	if sh := lookupShadow(pw.Name); sh != nil {
		stored = sh.Passwd
	}
	if stored == "" {
		return opts.AllowBlankPass && provided == ""
	}
	// crypt compare
	hashed := cryptHash(provided, stored)
	if hashed == "" {
		return false
	}
	return hashed == stored
}

var _ = io.EOF
var _ = strings.Join
