					sess.lastActivity = now // approximate: we sent keepalive, wait for response which counts as activity when received
					// To avoid spamming, update a separate keepalive sent time: reuse lastActivity but incoming response will update again.
				}
				continue
			}
			sess.finishExit(exitReasonFromErr(err))
			return
		}
		sess.conn.SetReadDeadline(time.Time{})
		sess.lastActivity = time.Now()
		if len(p) == 0 {
			continue
		}
		switch p[0] {
		case msgKexInit:
			if err := sess.trans.handleKex(p); err != nil {
				sess.finishExit(exitReasonFromErr(err))
