func (sess *session) mainLoop() {
	// keepalive / idle timeout ticker managed alongside reads using deadlines?
	// For simplicity, set read deadlines periodically in a goroutine? We handle timers in loop with conn deadlines.
	for {
		// set deadline for idle/keepalive handling if configured
		if sess.opts.IdleTimeout > 0 || sess.opts.Keepalive > 0 {
			// use a short poll deadline to check timers
			deadline := time.Now().Add(500 * time.Millisecond)
			sess.conn.SetReadDeadline(deadline)
		} else {
			sess.conn.SetReadDeadline(time.Time{})
		}
		p, err := sess.trans.readPacket()
		if err != nil {
			if isTimeoutErr(err) {
				// check timers
				now := time.Now()
				if sess.opts.IdleTimeout > 0 && now.Sub(sess.lastActivity) > time.Duration(sess.opts.IdleTimeout)*time.Second {
					sess.finishExit("Idle timeout")
					return
				}
				if sess.opts.Keepalive > 0 && now.Sub(sess.lastActivity) > time.Duration(sess.opts.Keepalive)*time.Second {
					// send keepalive global request keepalive@openssh.com wantreply=1
					w := &writer{}
					w.byte(msgGlobalRequest)
					w.str("keepalive@openssh.com")
					w.bool(true)
					sess.trans.writePacket(w.Bytes())
					sess.lastActivity = now // approximate: we sent keepalive, wait for response which counts as activity when received
					// To avoid spamming, update a separate keepalive sent time: reuse lastActivity but incoming response will update again.
				}
				continue
			}
			sess.finishExit(exitReasonFromErr(err))
			return
		}
		sess.conn.SetReadDeadline(time.Time{})
		sess.lastActivity = time.Now()
		if len(p) == 0 {
			continue
		}
		switch p[0] {
		case msgKexInit:
			if err := sess.trans.handleKex(p); err != nil {
				sess.finishExit(exitReasonFromErr(err))
				return
			}
		case msgDisconnect:
			sess.finishExit("Disconnect received")
			return
		case msgIgnore, msgDebug, msgExtInfo, msgUnimplemented:
			continue
		case msgGlobalRequest:
			sess.handleGlobalRequest(p)
		case msgChannelOpen:
			sess.handleChannelOpen(p)
		case msgChannelOpenConfirm:
			sess.handleChannelOpenConfirm(p)
		case msgChannelOpenFail:
			sess.handleChannelOpenFail(p)
		case msgChannelWindowAdjust, msgChannelData, msgChannelExtendedData, msgChannelEOF, msgChannelClose, msgChannelRequest, msgChannelSuccess, msgChannelFailure:
			sess.dispatchChannelPacket(p)
		default:
			w := &writer{}
			w.byte(msgUnimplemented)
			w.uint32(sess.trans.recvSeq - 1)
			sess.trans.writePacket(w.Bytes())
		}
		_ = fmt.Sprintf
	}
}

func isTimeoutErr(err error) bool {
	type netErr interface{ Timeout() bool }
	if ne, ok := err.(netErr); ok && ne.Timeout() {
		return true
	}
	return false
}

func (sess *session) cleanup() {
	sess.forwardsMu.Lock()
	for _, fl := range sess.forwards {
		fl.ln.Close()
	}
	sess.forwards = make(map[string]*forwardListener)
	sess.forwardsMu.Unlock()
	if sess.agentListener != nil {
		sess.agentListener.Close()
	}
	if sess.agentDir != "" {
