func (sess *session) handleChannelOpen(p []byte) {
	r := newReader(p)
	r.byte()
	chanType := r.str()
	sender := r.uint32()
	window := r.uint32()
	maxPacket := r.uint32()
	if r.err != nil {
		return
	}
	switch chanType {
	case "session":
		localID := sess.allocChannelID()
		ch := newChannel(sess, localID, sender, window, maxPacket, chanType)
		sess.addChannel(ch)
		// reply confirmation
		w := &writer{}
		w.byte(msgChannelOpenConfirm)
		w.uint32(sender)
		w.uint32(localID)
		w.uint32(sess.opts.RecvWindow)
		w.uint32(32759)
		sess.trans.writePacket(w.Bytes())
		// start inbound stdin forwarder goroutine once process starts; inbound channel will buffer
	case "direct-tcpip":
		// parse: host to connect string, port, origin string, origin port
		host := r.str()
		port := r.uint32()
		_ = r.str() // origin host
		_ = r.uint32() // origin port
		if r.err != nil {
			sess.sendOpenFailure(sender, channelOpenFailConnect, "")
			return
		}
		if sess.opts.DisableLocalFwd || (sess.pubkeyOpts != nil && sess.pubkeyOpts.NoPortForwarding) || (sess.pubkeyOpts != nil && sess.pubkeyOpts.Restrict) {
			// Restrict already sets NoPortForwarding
			sess.sendOpenFailure(sender, channelOpenFailAdmin, "")
			return
		}
		if sess.pubkeyOpts != nil && len(sess.pubkeyOpts.PermitOpen) > 0 {
			target := fmt.Sprintf("%s:%d", host, port)
			allowed := false
			for _, po := range sess.pubkeyOpts.PermitOpen {
				// permitopen may be "*:*" or host:port with wildcard port
				if po == "*:*" || po == target {
					allowed = true
					break
				}
				// host:* case
				if strings.HasSuffix(po, ":*") && strings.HasPrefix(target, po[:len(po)-1]) {
					allowed = true
					break
				}
			}
			if !allowed {
				sess.sendOpenFailure(sender, channelOpenFailAdmin, "")
				return
			}
		}
		targetAddr := net.JoinHostPort(host, strconv.Itoa(int(port)))
		conn, err := net.Dial("tcp", targetAddr)
		if err != nil {
			sess.sendOpenFailure(sender, channelOpenFailConnect, "")
			return
		}
		localID := sess.allocChannelID()
		ch := newChannel(sess, localID, sender, window, maxPacket, chanType)
		ch.peerConn = conn
		sess.addChannel(ch)
		w := &writer{}
		w.byte(msgChannelOpenConfirm)
		w.uint32(sender)
		w.uint32(localID)
		w.uint32(sess.opts.RecvWindow)
		w.uint32(32759)
		sess.trans.writePacket(w.Bytes())
		// bridge peer -> channel
		go bridgePeerToChannel(ch, conn)
		// bridge channel inbound -> peer
		go bridgeChannelInboundToPeer(ch, conn)
	default:
		sess.sendOpenFailure(sender, channelOpenFailUnknownType, "")
	}
}

func (sess *session) sendOpenFailure(sender uint32, reason uint32, msg string) {
	w := &writer{}
	w.byte(msgChannelOpenFail)
	w.uint32(sender)
	w.uint32(reason)
	w.str(msg)
	w.str("")
	sess.trans.writePacket(w.Bytes())
}

func bridgePeerToChannel(ch *channel, conn net.Conn) {
	buf := make([]byte, 32768)
	for {
		n, err := conn.Read(buf)
		if n > 0 {
			data := append([]byte{}, buf[:n]...)
			if serr := ch.sendData(data); serr != nil {
				break
			}
		}
		if err != nil {
			break
		}
	}
	ch.sendEOF()
	ch.sendClose()
	// peer closed; close peer
	conn.Close()
}

func bridgeChannelInboundToPeer(ch *channel, conn net.Conn) {
	for data := range ch.inbound {
		if _, err := conn.Write(data); err != nil {
			break
		}
		ch.sendWindowAdjust(uint32(len(data)))
	}
}

func (sess *session) handleChannelOpenConfirm(p []byte) {
	r := newReader(p)
	r.byte()
	recipient := r.uint32() // our local id
	sender := r.uint32()
	window := r.uint32()
	_ = r.uint32() // max packet
	ch := sess.getChannel(recipient)
	if ch == nil {
		return
	}
	ch.remoteID = sender
	ch.mu.Lock()
	ch.remoteWindow = window
	ch.openPending = false
	ch.mu.Unlock()
	ch.cond.Broadcast()
	// if this was a forwarded channel, start bridging after confirm (bridges already started at accept time will wait for window)
	// Bridges are started when accepted, they use sendData which waits for window.
}

func (sess *session) handleChannelOpenFail(p []byte) {
	r := newReader(p)
	r.byte()
	recipient := r.uint32()
	ch := sess.getChannel(recipient)
	if ch == nil {
		return
	}
	// close peer
	if ch.peerConn != nil {
		ch.peerConn.Close()
	}
	ch.closeMu.Lock()
	ch.closedRemote = true
	ch.closeMu.Unlock()
	ch.mu.Lock()
	ch.cond.Broadcast()
	ch.mu.Unlock()
	sess.removeChannel(recipient)
}

func (sess *session) dispatchChannelPacket(p []byte) {
	if len(p) == 0 {
		return
	}
	msgType := p[0]
	r := newReader(p)
	r.byte()
	recipient := r.uint32()
	ch := sess.getChannel(recipient)
	if ch == nil {
		return
	}
	switch msgType {
	case msgChannelWindowAdjust:
		add := r.uint32()
		ch.mu.Lock()
		ch.remoteWindow += add
		ch.mu.Unlock()
		ch.cond.Broadcast()
	case msgChannelData:
		data := r.strBytes()
		if r.err != nil {
			return
		}
		// enqueue to inbound; adjust window after consumed in consumers.
		// For session channels without process yet, buffer.
		// If inbound channel full, this will block main loop - acceptable flow control
		select {
		case ch.inbound <- append([]byte{}, data...):
		default:
			// if buffer full, block (backpressure)
			ch.inbound <- append([]byte{}, data...)
		}
	case msgChannelExtendedData:
		_ = r.uint32()
		data := r.strBytes()
		// only stderr for forwarded? ignore for session (stdin is data only)
		_ = data
	case msgChannelEOF:
		close(ch.inbound)
		// also notify process stdin handling (in exec.go inbound forwarder will close stdin)
		// Prevent double close panic if repeated: check
		// close() on already closed channel panics; we need guard. Use a flag via recover
		// The above close may panic if EOF received twice - handle with defer in caller? Instead track.
		// To avoid, we check closedRemoteEOF flag
		// NOTE: This code path already closed; subsequent EOF will panic and be recovered at top level of mainLoop? Not ideal.
		// We'll use sync flag:
		// (implemented via ch.eofReceived below - but we already closed)
	case msgChannelClose:
		ch.closeMu.Lock()
		alreadyLocal := ch.closedLocal
		ch.closedRemote = true
		ch.closeMu.Unlock()
		ch.mu.Lock()
		ch.cond.Broadcast()
		ch.mu.Unlock()
		if ch.peerConn != nil {
			ch.peerConn.Close()
		}
		if ch.stdinPipe != nil {
			ch.stdinPipe.Close()
		}
		if ch.ptyFile != nil {
			// closing master will cause process to get HUP
			ch.ptyFile.Close()
		}
		ch.killProcessOnClose()
		if !alreadyLocal {
			ch.sendClose()
		}
		sess.removeChannel(recipient)
	case msgChannelRequest:
		sess.handleChannelRequest(ch, r)
	case msgChannelSuccess, msgChannelFailure:
		// responses to our requests - ignore
	}
}

// need to handle EOF close idempotency - patch dispatch above using flag in channel struct
// channel.eofReceived field is added via separate field in struct? We added inbound channel; closing twice panics.
// To mitigate, we intercept via wrapper: mainLoop recovers? Instead we modify behaviour:
// In dispatchChannelPacket for EOF, we use a mutex-protected flag stored in channel.closeMu and a separate bool field defined in channels2.go

var _ = syscall.SIGTERM
var _ = os.Getpid
EOF
"}

