			ch.ptyFile.Close()
		}
		ch.killProcessOnClose()
		if !alreadyLocal {
			ch.sendClose()
		}
		sess.removeChannel(recipient)
	case msgChannelRequest:
		sess.handleChannelRequest(ch, r)
	case msgChannelSuccess, msgChannelFailure:
		// responses to our requests - ignore
	}
