package main

import (
	"fmt"
	"net"
	"strconv"
)

func (sess *session) handleGlobalRequest(p []byte) {
	r := newReader(p)
	r.byte()
	reqType := r.str()
	wantReply := r.bool()
	switch reqType {
	case "tcpip-forward":
		bindAddr := r.str()
		bindPort := r.uint32()
		if r.err != nil {
			if wantReply { sess.sendGlobalFailure() }
			return
		}
		if sess.opts.DisableRemoteFwd || (sess.pubkeyOpts != nil && sess.pubkeyOpts.NoPortForwarding) {
			if wantReply { sess.sendGlobalFailure() }
			return
		}
		// bind
		fl, err := sess.startForward(bindAddr, bindPort)
		if err != nil {
			if wantReply { sess.sendGlobalFailure() }
			return
		}
		if wantReply {
			w := &writer{}
			w.byte(msgRequestSuccess)
			// if requested port 0, include allocated port
			if bindPort == 0 {
				w.uint32(fl.port)
			}
			sess.trans.writePacket(w.Bytes())
		}
	case "cancel-tcpip-forward":
		bindAddr := r.str()
		bindPort := r.uint32()
		key := forwardKey(bindAddr, bindPort)
		sess.forwardsMu.Lock()
		fl, ok := sess.forwards[key]
		if ok {
			delete(sess.forwards, key)
		}
		sess.forwardsMu.Unlock()
		if ok {
			fl.ln.Close()
			if wantReply { sess.sendGlobalSuccessEmpty() }
		} else {
			if wantReply { sess.sendGlobalFailure() }
		}
	case "keepalive@openssh.com":
		if wantReply { sess.sendGlobalSuccessEmpty() }
	case "no-more-sessions@openssh.com":
		if wantReply { sess.sendGlobalSuccessEmpty() }
	default:
		if wantReply { sess.sendGlobalFailure() }
	}
}

func (sess *session) sendGlobalSuccessEmpty() {
	w := &writer{}
	w.byte(msgRequestSuccess)
	sess.trans.writePacket(w.Bytes())
}
func (sess *session) sendGlobalFailure() {
	w := &writer{}
	w.byte(msgRequestFailure)
	sess.trans.writePacket(w.Bytes())
}

func forwardKey(addr string, port uint32) string {
	return fmt.Sprintf("%s:%d", addr, port)
}

func (sess *session) startForward(bindAddr string, bindPort uint32) (*forwardListener, error) {
	// determine listen address
	var listenAddr string
	if sess.opts.AllowAnyFwd {
		// bind wildcard
		listenAddr = net.JoinHostPort("", strconv.Itoa(int(bindPort)))
		// empty host with Join gives :port
	} else {
		host := bindAddr
		if host == "" || host == "localhost" {
			host = "127.0.0.1"
		}
		listenAddr = net.JoinHostPort(host, strconv.Itoa(int(bindPort)))
	}
	ln, err := net.Listen("tcp", listenAddr)
	if err != nil {
		return nil, err
	}
	actualPort := uint32(ln.Addr().(*net.TCPAddr).Port)
	key := forwardKey(bindAddr, bindPort)
	// If port 0 requested, original key should be by allocated? cancel will come with allocated port and bind addr; store also under allocated port
	fl := &forwardListener{ln: ln, bindAddr: bindAddr, port: actualPort}
	sess.forwardsMu.Lock()
	sess.forwards[key] = fl
	if bindPort == 0 {
		sess.forwards[forwardKey(bindAddr, actualPort)] = fl
	}
	sess.forwardsMu.Unlock()
	go sess.acceptForward(fl, bindAddr, actualPort)
	return fl, nil
}

func (sess *session) acceptForward(fl *forwardListener, bindAddr string, bindPort uint32) {
	for {
		conn, err := fl.ln.Accept()
		if err != nil {
			return
		}
		go sess.openForwardedChannel(fl, bindAddr, bindPort, conn)
	}
}

func (sess *session) openForwardedChannel(fl *forwardListener, bindAddr string, bindPort uint32, conn net.Conn) {
	localID := sess.allocChannelID()
	ch := newChannel(sess, localID, 0, 0, 0, "forwarded-tcpip")
	ch.peerConn = conn
	ch.openPending = true
	sess.addChannel(ch)
	// connected address: the address/port that was being forwarded (bind addr/port as client expects)
	connectedAddr := bindAddr
	if connectedAddr == "" {
		// use listener local address IP
		if ta, ok := fl.ln.Addr().(*net.TCPAddr); ok {
			connectedAddr = ta.IP.String()
		}
	}
	originIP := ""
	var originPort int
	if ta, ok := conn.RemoteAddr().(*net.TCPAddr); ok {
		originIP = ta.IP.String()
		originPort = ta.Port
	}
	w := &writer{}
	w.byte(msgChannelOpen)
	w.str("forwarded-tcpip")
	w.uint32(localID)
	w.uint32(sess.opts.RecvWindow)
	w.uint32(32759)
	w.str(connectedAddr)
	w.uint32(bindPort)
	w.str(originIP)
	w.uint32(uint32(originPort))
	if err := sess.trans.writePacket(w.Bytes()); err != nil {
		conn.Close()
		sess.removeChannel(localID)
		return
	}
	// bridges: they will block on sendData until window available after confirm
	go bridgePeerToChannel(ch, conn)
	go bridgeChannelInboundToPeer(ch, conn)
}
EOF
"}

