{"command":"cat > exec.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
)

type ptyInfo struct {
	term string
	cols uint32
	rows uint32
	widthPx uint32
	heightPx uint32
	modes []byte
}

// channel fields extension for process handling
// stored in channel struct's cmd as *exec.Cmd

func (ch *channel) killProcess() {
	if ch.cmd != nil {
		if ec, ok := ch.cmd.(*exec.Cmd); ok && ec.Process != nil {
			ec.Process.Kill()
		}
	}
}
func (ch *channel) killProcessOnClose() {
	// On channel close from client, terminate process with SIGHUP if running (mimic disconnect)
	if ch.cmd != nil {
		if ec, ok := ch.cmd.(*exec.Cmd); ok && ec.Process != nil {
			// send SIGHUP to process group if possible
			// process is session leader, pgid = pid
			syscall.Kill(-ec.Process.Pid, syscall.SIGHUP)
			// also kill after brief? killProcess cleanup will handle
		}
	}
}

func (sess *session) handleChannelRequest(ch *channel, r *reader) {
	reqType := r.str()
	wantReply := r.bool()
	switch reqType {
	case "pty-req":
		term := r.str()
		cols := r.uint32()
		rows := r.uint32()
		wpx := r.uint32()
		hpx := r.uint32()
		modes := r.strBytes()
		if sess.pubkeyOpts != nil && sess.pubkeyOpts.NoPty {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		ch.pty = &ptyInfo{term: term, cols: cols, rows: rows, widthPx: wpx, heightPx: hpx, modes: modes}
		if wantReply { ch.sendRequestSuccess() }
	case "env":
		// dropbear rejects all env requests
		_ = r.str()
		_ = r.str()
		if wantReply { ch.sendRequestFailure() }
	case "shell":
		if ch.execStarted {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		ch.execType = "shell"
		ch.execCmd = ""
		if err := sess.startSessionProcess(ch, wantReply); err != nil {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		if wantReply { ch.sendRequestSuccess() }
	case "exec":
		cmdStr := r.str()
		if ch.execStarted {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		ch.execType = "exec"
		ch.execCmd = cmdStr
		if err := sess.startSessionProcess(ch, wantReply); err != nil {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		if wantReply { ch.sendRequestSuccess() }
	case "subsystem":
		name := r.str()
		if ch.execStarted {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		if name != "sftp" {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		ch.execType = "subsystem"
		ch.subsystemName = name
		// command is /usr/libexec/sftp-server executed via shell
		ch.execCmd = "/usr/libexec/sftp-server"
		if err := sess.startSessionProcess(ch, wantReply); err != nil {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		if wantReply { ch.sendRequestSuccess() }
	case "window-change":
		cols := r.uint32()
		rows := r.uint32()
		_ = r.uint32()
		_ = r.uint32()
		if ch.pty != nil {
			ch.pty.cols = cols
			ch.pty.rows = rows
			if ch.ptyFile != nil {
				setWindowSize(ch.ptyFile, cols, rows)
			}
		}
		// no reply (wantReply should be false)
	case "signal":
		sigName := r.str()
		ch.signalProcess(sigName)
	case "auth-agent-req@openssh.com", "auth-agent-req":
		if sess.pubkeyOpts != nil && sess.pubkeyOpts.NoAgentForwarding {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		if err := sess.setupAgentForwarding(ch); err != nil {
			if wantReply { ch.sendRequestFailure() }
			return
		}
		if wantReply { ch.sendRequestSuccess() }
	case "x11-req":
		// consume fields
		// bool single, string auth proto, string auth cookie, uint32 screen
		_ = r.bool()
		_ = r.str()
		_ = r.str()
		_ = r.uint32()
		if wantReply { ch.sendRequestFailure() }
	case "exit-status":
		// client shouldn't send, ignore
	case "exit-signal":
		// ignore
	default:
		if wantReply { ch.sendRequestFailure() }
	}
}

func (ch *channel) signalProcess(sigName string) {
	if ch.cmd == nil {
		return
	}
	ec, ok := ch.cmd.(*exec.Cmd)
	if !ok || ec.Process == nil {
		return
	}
	var sig syscall.Signal
	switch strings.ToUpper(sigName) {
	case "HUP": sig = syscall.SIGHUP
	case "INT": sig = syscall.SIGINT
	case "QUIT": sig = syscall.SIGQUIT
	case "TERM": sig = syscall.SIGTERM
	case "KILL": sig = syscall.SIGKILL
	case "USR1": sig = syscall.SIGUSR1
	case "USR2": sig = syscall.SIGUSR2
	case "PIPE": sig = syscall.SIGPIPE
	case "ALRM": sig = syscall.SIGALRM
	case "ABRT": sig = syscall.SIGABRT
	case "SEGV": sig = syscall.SIGSEGV
	case "BUS": sig = syscall.SIGBUS
	case "FPE": sig = syscall.SIGFPE
	case "ILL": sig = syscall.SIGILL
	case "SYS": sig = syscall.SIGSYS
	case "TRAP": sig = syscall.SIGTRAP
	case "XCPU": sig = syscall.SIGXCPU
	case "XFSZ": sig = syscall.SIGXFSZ
	default:
		// numeric?
		return
	}
	ec.Process.Signal(sig)
}

func (sess *session) buildEnv(ch *channel, originalCmd string, isShell bool, hasOriginal bool) []string {
	var envMap = make(map[string]string)
	var order []string
	set := func(k, v string) {
		if _, ok := envMap[k]; !ok {
			order = append(order, k)
		}
		envMap[k] = v
	}
	if sess.opts.PassEnv {
		for _, e := range os.Environ() {
			kv := strings.SplitN(e, "=", 2)
			if len(kv) == 2 {
				set(kv[0], kv[1])
			} else {
				set(kv[0], "")
			}
		}
	}
	// set defaults overriding
	user := sess.pw
	set("HOME", user.Home)
	set("LOGNAME", user.Name)
	set("USER", user.Name)
	set("SHELL", user.Shell)
	set("PATH", "/usr/bin:/bin")
	if ch != nil && ch.pty != nil {
		set("TERM", ch.pty.term)
		if ttyName := ch.ptyTTYName(); ttyName != "" {
			set("SSH_TTY", ttyName)
		}
	}
	set("SSH_CLIENT", fmt.Sprintf("%s %d %d", sess.remoteIP, sess.remotePort, sess.localPort))
	set("SSH_CONNECTION", fmt.Sprintf("%s %d %s %d", sess.remoteIP, sess.remotePort, sess.localIP, sess.localPort))
	if sess.usedPubkey && sess.pubkeyInfo != "" {
		set("SSH_PUBKEYINFO", sess.pubkeyInfo)
	}
	if sess.agentPath != "" {
		set("SSH_AUTH_SOCK", sess.agentPath)
	}
	// forced command handling sets SSH_ORIGINAL_COMMAND
	hasForced := sess.opts.HasForcedCommand || (sess.pubkeyOpts != nil && sess.pubkeyOpts.HasForcedCommand)
	if hasForced {
		oc := ""
		if hasOriginal {
			oc = originalCmd
		}
		set("SSH_ORIGINAL_COMMAND", oc)
	}
	// If running subsystem sftp and ??? OpenSSH drops SSH_ORIGINAL? For forced, original is subsystem command?
	var env []string
	for _, k := range order {
		env = append(env, k+"="+envMap[k])
	}
	return env
}

func (ch *channel) ptyTTYName() string {
	if ch.ptyFile != nil {
		// we stored tty name elsewhere? use fd link
		if name, err := filepath.EvalSymlinks(fmt.Sprintf("/proc/self/fd/%d", ch.ptyFile.Fd())); err == nil {
			return name
		}
	}
	if ch.pty != nil && ch.cmd != nil {
		// fallback, not accurate
	}
	return ch.ptySlaveName
}

// startSessionProcess launches shell/exec/subsystem
func (sess *session) startSessionProcess(ch *channel, wantReply bool) error {
	if ch.execStarted {
		return fmt.Errorf("already started")
	}
	user := sess.pw
	shellPath := user.Shell
	if shellPath == "" {
		shellPath = "/bin/sh"
	}
	shellBase := filepath.Base(shellPath)

	// Determine command to run
	var argv []string
	var cmdToRun string // for shell -c
	isShellReq := false
	hasOriginal := false
	originalCmd := ""

	if ch.execType == "shell" {
		isShellReq = true
		hasOriginal = true // SSH_ORIGINAL_COMMAND will be ""
		originalCmd = ""
	} else if ch.execType == "exec" {
		cmdToRun = ch.execCmd
		originalCmd = ch.execCmd
		hasOriginal = true
	} else if ch.execType == "subsystem" {
		cmdToRun = ch.execCmd // /usr/libexec/sftp-server
		originalCmd = ch.execCmd
		hasOriginal = true // ??? for forced case, original would be ??? We'll treat as exec
	}

	// forced command overrides
	forced := ""
	hasForced := false
	if sess.opts.HasForcedCommand {
		forced = sess.opts.ForcedCommand
		hasForced = true
	} else if sess.pubkeyOpts != nil && sess.pubkeyOpts.HasForcedCommand {
		forced = sess.pubkeyOpts.ForcedCommand
		hasForced = true
	}
	if hasForced {
		cmdToRun = forced
		isShellReq = false
		// original already set
		// if the request was shell, original is "" (hasOriginal true)
		// if exec, original is execCmd
		// if subsystem, what is original? Keep as execCmd
	}

	// MOTD for shell requests (original request type shell, even if forced?)
	if ch.execType == "shell" && !sess.opts.NoMotd {
		if data, err := os.ReadFile("/etc/motd"); err == nil && len(data) > 0 {
			// send as channel data
			ch.sendData(data)
		}
	}

	ch.execStarted = true

	// Prepare process
	var cmd *exec.Cmd
	if isShellReq && !hasForced {
		// login shell
		cmd = exec.Command(shellPath)
		cmd.Args = []string{"-" + shellBase}
	} else {
		cmd = exec.Command(shellPath)
		cmd.Args = []string{shellBase, "-c", cmdToRun}
	}
	cmd.Dir = user.Home
	// environment: need pty slave name before env for SSH_TTY; build after pty allocation if needed
	// PTY handling
	usePty := ch.pty != nil
	if usePty {
		master, slave, slaveName, err := openPty(ch.pty.cols, ch.pty.rows, ch.pty.modes)
		if err != nil {
			ch.execStarted = false
			return err
		}
		ch.ptyFile = master
		ch.ptySlaveName = slaveName
		cmd.Stdin = slave
		cmd.Stdout = slave
		cmd.Stderr = slave
		cmd.SysProcAttr = &syscall.SysProcAttr{
			Setsid: true,
			Setctty: true,
			Ctty: 0,
		}
		// credential if root
		applyCredential(cmd, user)
		cmd.Env = sess.buildEnv(ch, originalCmd, isShellReq, hasOriginal)
		err = cmd.Start()
		slave.Close()
		if err != nil {
			master.Close()
			ch.execStarted = false
			return err
		}
		ch.cmd = cmd
		// inbound stdin -> pty master
		go func() {
			for data := range ch.inbound {
				// writing to pty master
				if _, err := master.Write(data); err != nil {
					break
				}
				ch.sendWindowAdjust(uint32(len(data)))
			}
			// client EOF: for pty, dropbear probably does not close pty; do nothing
		}()
		// pty output -> channel
		go func() {
			buf := make([]byte, 32768)
			for {
				n, err := master.Read(buf)
				if n > 0 {
					data := append([]byte{}, buf[:n]...)
					if serr := ch.sendData(data); serr != nil {
						break
					}
				}
				if err != nil {
					break
				}
			}
		}()
		// wait for process
		go sess.waitSessionProcess(ch, cmd)
		return nil
	}

	// Non-PTY
	stdinPipe, err := cmd.StdinPipe()
	if err != nil {
		ch.execStarted = false
		return err
	}
	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		ch.execStarted = false
		return err
	}
	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		ch.execStarted = false
		return err
	}
	ch.stdinPipe = stdinPipe
	cmd.SysProcAttr = &syscall.SysProcAttr{
		Setsid: true,
	}
	applyCredential(cmd, user)
	cmd.Env = sess.buildEnv(ch, originalCmd, isShellReq, hasOriginal)
	if err := cmd.Start(); err != nil {
		ch.execStarted = false
		return err
	}
	ch.cmd = cmd

	// stdin forwarder
	go func() {
		for data := range ch.inbound {
			if _, err := stdinPipe.Write(data); err != nil {
				break
			}
			ch.sendWindowAdjust(uint32(len(data)))
		}
		stdinPipe.Close()
	}()
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		io.Copy(channelWriter{ch, false}, stdoutPipe)
	}()
	go func() {
		defer wg.Done()
		io.Copy(channelWriter{ch, true}, stderrPipe)
	}()
	go func() {
		wg.Wait()
		// outputs drained; wait process in waitSessionProcess will send status after cmd.Wait - but we already are using pipes, cmd.Wait must be called after reads finish.
		// waitSessionProcess will handle
	}()
	go sess.waitSessionProcess(ch, cmd)
	return nil
}

type channelWriter struct {
	ch *channel
	isStderr bool
}
func (cw channelWriter) Write(p []byte) (int, error) {
	if cw.isStderr {
		if err := cw.ch.sendExtendedData(1, p); err != nil {
			return 0, err
		}
	} else {
		if err := cw.ch.sendData(p); err != nil {
			return 0, err
		}
	}
	return len(p), nil
}

func applyCredential(cmd *exec.Cmd, user *PasswdEntry) {
	if getEuid() != 0 {
		return
	}
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	groups := supplementaryGids(user)
	cmd.SysProcAttr.Credential = &syscall.Credential{
		Uid: uint32(user.UID),
		Gid: uint32(user.GID),
		Groups: groups,
	}
}

func (sess *session) waitSessionProcess(ch *channel, cmd *exec.Cmd) {
	err := cmd.Wait()
	// Drain is handled by copy goroutines for non-pty; for pty output goroutine will end when master closed.
	// Give a brief moment for output copy to flush: for non-pty, cmd.Wait returns after pipes closed but copy may need to finish sending.
	// We rely on io.Copy goroutines: they are reading pipes which close on process exit, they will send data before we send EOF.
	// To synchronize, we don't have wg handle here; add small delay logic: if not pty, wait until stdout/stderr copies likely done.
	// Alternative: use a wait group stored on channel - simplified delay
	if ch.pty == nil {
		// wait a tiny bit for copy goroutines to flush. The copy goroutines are blocked on channel window; they should complete quickly.
		// Poll for ??? We use a channel processOutputDone if set.
		if ch.outputDone != nil {
			<-ch.outputDone
		}
	} else {
		if ch.ptyFile != nil {
			// closing master will cause reader to exit
			// leave it; reader will get EIO after slave closed by child exit
		}
	}
	// send EOF
	ch.sendEOF()
	// send exit status / signal
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			if ws, ok := exitErr.Sys().(syscall.WaitStatus); ok {
				if ws.Signaled() {
					sig := ws.Signal()
					name := signalName(sig)
					w := &writer{}
					w.byte(msgChannelRequest)
					w.uint32(ch.remoteID)
					w.str("exit-signal")
					w.bool(false)
					w.str(name)
					w.bool(ws.CoreDump())
					w.str("")
					w.str("")
					sess.trans.writePacket(w.Bytes())
					ch.sendClose()
					sess.removeChannel(ch.localID)
					closeChannelInbound(ch)
					return
				}
			}
		}
	}
	status := 0
	if cmd.ProcessState != nil {
		status = cmd.ProcessState.ExitCode()
		if status < 0 {
			status = 255
		}
	}
	{
		w := &writer{}
		w.byte(msgChannelRequest)
		w.uint32(ch.remoteID)
		w.str("exit-status")
		w.bool(false)
		w.uint32(uint32(status))
		sess.trans.writePacket(w.Bytes())
	}
	ch.sendClose()
	sess.removeChannel(ch.localID)
	// close pty master etc
	if ch.ptyFile != nil {
		ch.ptyFile.Close()
	}
}

func closeChannelInbound(ch *channel) {
	ch.closeMu.Lock()
	if !ch.eofReceived {
		ch.eofReceived = true
		// inbound may already be closed; ignore
		defer func() { recover() }()
		close(ch.inbound)
	}
	ch.closeMu.Unlock()
}

func signalName(sig syscall.Signal) string {
	// name without SIG prefix, uppercase
	s := sig.String() // e.g., "terminated"? On Linux Go's Signal String returns "hangup" etc for some, but for syscall signals it may be descriptive.
	// Map manually
	switch sig {
	case syscall.SIGHUP: return "HUP"
	case syscall.SIGINT: return "INT"
	case syscall.SIGQUIT: return "QUIT"
	case syscall.SIGILL: return "ILL"
	case syscall.SIGTRAP: return "TRAP"
	case syscall.SIGABRT: return "ABRT"
	case syscall.SIGBUS: return "BUS"
	case syscall.SIGFPE: return "FPE"
	case syscall.SIGKILL: return "KILL"
	case syscall.SIGUSR1: return "USR1"
	case syscall.SIGSEGV: return "SEGV"
	case syscall.SIGUSR2: return "USR2"
	case syscall.SIGPIPE: return "PIPE"
	case syscall.SIGALRM: return "ALRM"
	case syscall.SIGTERM: return "TERM"
	default:
		return strings.TrimPrefix(strings.ToUpper(s), "SIG")
	}
}

// agent forwarding
func (sess *session) setupAgentForwarding(ch *channel) error {
	if sess.agentListener != nil {
		return nil
	}
	// create directory /tmp/dropbear-XXXXXX
	dir, err := os.MkdirTemp("/tmp", "dropbear-")
	if err != nil {
		return err
	}
	// dropbear naming: /tmp/dropbear-<something>/auth-<something>
	// Our dir already is /tmp/dropbear-<random>; create socket inside as auth-<random>
	// Generate suffix from pid/time
	sockName := fmt.Sprintf("auth-%x", os.Getpid())
	// To mimic observed long numbers, use random hex? Keep simple
	path := filepath.Join(dir, sockName)
	ln, err := net.Listen("unix", path)
	if err != nil {
		os.RemoveAll(dir)
		return err
	}
	// permissions: dir 0700 by MkdirTemp, socket default
	sess.agentListener = ln
	sess.agentPath = path
	sess.agentDir = dir
	go sess.acceptAgentConnections(ln)
	return nil
}

func (sess *session) acceptAgentConnections(ln net.Listener) {
	for {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		go sess.openAgentChannel(conn)
	}
}

func (sess *session) openAgentChannel(conn net.Conn) {
	localID := sess.allocChannelID()
	ch := newChannel(sess, localID, 0, 0, 0, "auth-agent@openssh.com")
	ch.peerConn = conn
	ch.openPending = true
	sess.addChannel(ch)
	w := &writer{}
	w.byte(msgChannelOpen)
	w.str("auth-agent@openssh.com")
	w.uint32(localID)
	w.uint32(sess.opts.RecvWindow)
	w.uint32(32759)
	if err := sess.trans.writePacket(w.Bytes()); err != nil {
		conn.Close()
		sess.removeChannel(localID)
		return
	}
	go bridgePeerToChannel(ch, conn)
	go bridgeChannelInboundToPeer(ch, conn)
}
EOF
"}

