func parsePortSpec(value string) PortSpec {
	// split at last colon
	idx := strings.LastIndex(value, ":")
	if idx >= 0 {
		host := value[:idx]
		port := value[idx+1:]
		if port == "" {
			logMsg("Early exit: Bad port")
			os.Exit(1)
		}
		return PortSpec{Original: value, Host: host, PortStr: port}
	}
	return PortSpec{Original: value, Host: "", PortStr: value}
}

func loadHostkeys(opts *Options) {
	var specs []string
	explicit := len(opts.HostKeyPaths) > 0
	if explicit {
		specs = opts.HostKeyPaths
	} else {
		specs = []string{defaultRSA, defaultECDSA, defaultED}
	}
	var entries []*HostKeyEntry
	loadedTypes := make(map[string]*HostKey) // display type e.g. RSA
	anyLoaded := false

	// helper to load one
	loadOne := func(path string) *HostKey {
		data, err := os.ReadFile(path)
		if err != nil {
			if !opts.CreateHostKeys {
				logMsg("Failed loading %s", path)
			}
			return nil
		}
		hk, perr := parseDropbearKey(data)
		if perr != nil {
			if kpe, ok := perr.(*keyParseError); ok {
				if kpe.kind == "failed" {
					if !opts.CreateHostKeys {
						logMsg("Failed loading %s", path)
					}
					return nil
				}
				// fatal
				logMsg("Early exit: %s", kpe.kind)
				os.Exit(1)
			}
			if !opts.CreateHostKeys {
				logMsg("Failed loading %s", path)
			}
			return nil
		}
		// duplicate detection
		disp := keyTypeDisplay(hk)
		if _, exists := loadedTypes[disp]; exists {
			logMsg("Early exit: Only one %s key can be specified", disp)
			os.Exit(1)
		}
		loadedTypes[disp] = hk
		entries = append(entries, &HostKeyEntry{Path: path, Data: data, Loaded: true})
		anyLoaded = true
		return hk
	}

	if opts.CreateHostKeys && explicit {
		// load explicit, missing become unknown delayed
		for _, p := range specs {
			before := len(entries)
			hk := loadOne(p)
			if hk == nil && len(entries) == before {
				// missing/invalid with -R: becomes delayed unknown (no log per observation)
				// But if file exists and is invalid parse 'failed', original with -R? It also would treat as delayed? We mimic missing.
				entries = append(entries, &HostKeyEntry{Path: p, Delayed: true, DelayType: ""})
			}
		}
		// add default delayed entries for families not loaded
		hasRSA, hasECDSA, hasED := false, false, false
		for disp := range loadedTypes {
			switch disp {
			case "RSA":
				hasRSA = true
			case "ECDSA256", "ECDSA384", "ECDSA521":
				hasECDSA = true
			case "ed25519":
				hasED = true
			}
		}
		if !hasRSA {
			entries = append(entries, &HostKeyEntry{Path: defaultRSA, Delayed: true, DelayType: "ssh-rsa"})
		}
		if !hasECDSA {
			entries = append(entries, &HostKeyEntry{Path: defaultECDSA, Delayed: true, DelayType: "ecdsa-sha2-nistp256"})
		}
		if !hasED {
			entries = append(entries, &HostKeyEntry{Path: defaultED, Delayed: true, DelayType: "ssh-ed25519"})
		}
		opts.Entries = entries
		return
	}

	if opts.CreateHostKeys && !explicit {
		// defaults delayed
		entries = append(entries,
			&HostKeyEntry{Path: defaultRSA, Delayed: true, DelayType: "ssh-rsa"},
			&HostKeyEntry{Path: defaultECDSA, Delayed: true, DelayType: "ecdsa-sha2-nistp256"},
			&HostKeyEntry{Path: defaultED, Delayed: true, DelayType: "ssh-ed25519"},
		)
		opts.Entries = entries
		return
	}

	// non -R path
	for _, p := range specs {
		loadOne(p)
	}
	if !anyLoaded {
		logMsg("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.")
		os.Exit(1)
	}
	opts.Entries = entries
}

func writePidFile(path string) {
	if path == "" {
		return
	}
	// try to write; ignore errors
	content := fmt.Sprintf("%d\n", os.Getpid())
	_ = os.WriteFile(path, []byte(content), 0644)
	// original creates file with default modes based on umask; writefile respects.
	// If file existed, truncation ok.
}

func setupListenerSignals() {
	sigc := make(chan os.Signal, 4)
	signal.Notify(sigc, syscall.SIGTERM, syscall.SIGINT)
	// ignore SIGPIPE like original
	signal.Ignore(syscall.SIGPIPE)
	go func() {
		<-sigc
		logMsg("Early exit: Terminated by signal")
		os.Exit(0)
	}()
}

func serveListeners(listeners []net.Listener, opts *Options) {
	// accept on all listeners
	errCh := make(chan struct{})
	for _, ln := range listeners {
		go acceptLoop(ln, opts)
	}
	_ = errCh
	// block forever
	select {}
}

func acceptLoop(ln net.Listener, opts *Options) {
	for {
		conn, err := ln.Accept()
		if err != nil {
			// listener closed or error - pause a bit
			time.Sleep(10 * time.Millisecond)
			continue
		}
		spawnChild(conn, opts)
	}
}

// spawn a child process to handle the connection, passing conn as fd 3
func spawnChild(conn net.Conn, opts *Options) {
	exe, err := os.Executable()
	if err != nil {
		conn.Close()
		return
	}
	cfgBytes, err := encodeConfig(opts)
	if err != nil {
		conn.Close()
		return
	}
	// pass conn as file
	tcpConn, ok := conn.(*net.TCPConn)
	if !ok {
		// generic: try to get file via type assertion for SyscallConn? Use a pipe fallback: handle in-process
		// For non-TCP (shouldn't happen), handle in goroutine
		go handleConnection(conn, opts)
		return
	}
	file, err := tcpConn.File()
	if err != nil {
		conn.Close()
		return
	}
	// file duplicates fd; after child starts we can close conn and file in parent
	defer file.Close()
	defer conn.Close()

	env := append(os.Environ(),
		"DROPBEAR_INTERNAL_CHILD=1",
		"DROPBEAR_INTERNAL_CONFIG="+base64.StdEncoding.EncodeToString(cfgBytes),
	)
	cmd := buildChildCmd(exe, env, file)
	// stdin /dev/null, stdout /dev/null (or same as parent? session I/O is over socket, process stdout should not go to server stdout)
	// Original dropbear child stdout is ??? Its children inherit server stdout, but session output is redirected to socket. For safety use /dev/null for stdin, and same stderr for logging.
	// stdout: if we inherit, stray writes may pollute server stdout; use nil (/dev/null)
	cmd.Stdin = nil
	cmd.Stdout = nil
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		return
	}
	// reap in background
	go cmd.Wait()
}

func buildChildCmd(exe string, env []string, file *os.File) cmdType {
	return newChildCmd(exe, env, file)
}

// type alias defined in child.go
type configPayload struct {
	Opts *Options `json:"opts"`
}

func encodeConfig(opts *Options) ([]byte, error) {
	return json.Marshal(configPayload{Opts: opts})
}
func decodeConfig(b []byte) (*Options, error) {
	var cp configPayload
	if err := json.Unmarshal(b, &cp); err != nil {
		return nil, err
	}
	return cp.Opts, nil
}
EOF
"}

