	defaultECDSA = "/etc/dropbear/dropbear_ecdsa_host_key"
	defaultED = "/etc/dropbear/dropbear_ed25519_host_key"
)

func main() {
	// internal child modes
	if os.Getenv("DROPBEAR_INTERNAL_CHILD") == "1" {
		runInternalChild()
		return
	}
	if os.Getenv("DROPBEAR_INTERNAL_DAEMON") == "1" {
		runInternalDaemon()
		return
	}
	runMain(os.Args)
}

func missingArgument() {
	logMsg("Early exit: Missing argument")
	os.Exit(1)
}

func runMain(argv []string) {
	prog := argv[0]
	opts := &Options{
		RecvWindow: 24576,
		MaxAuthTries: 10,
		PidFile: "/var/run/dropbear.pid",
	}
	// temporary string holders for options needing args
	args := argv[1:]
	i := 0
	// parsing loop
	for i < len(args) {
		arg := args[i]
		if len(arg) < 2 || arg[0] != '-' {
			// invalid argument ("-", "", plain, etc)
			logMsg("Early exit: Invalid argument: %s", arg)
			os.Exit(1)
		}
		// process characters
		j := 1
		consumedNext := false
		for j < len(arg) {
			c := arg[j]
			switch c {
			case 'h':
				printUsage(prog)
				os.Exit(0)
			case 'V':
				fmt.Fprintf(os.Stderr, "Dropbear v%s\n", versionString)
				os.Exit(0)
			case 'F':
				opts.Foreground = true
				j++
			case 'R':
				opts.CreateHostKeys = true
				j++
			case 'e':
				opts.PassEnv = true
				j++
			case 'm':
				opts.NoMotd = true
				j++
			case 'w':
				opts.DisallowRoot = true
				j++
			case 's':
				opts.DisablePass = true
				j++
			case 'g':
