				var value string
				if j+1 < len(arg) {
					value = arg[j+1:]
					j = len(arg)
				} else {
					if i+1 >= len(args) {
						missingArgument()
					}
					value = args[i+1]
					consumedNext = true
					j = len(arg)
				}
				switch c {
				case 'b':
					opts.BannerFile = value
					opts.HasBanner = true
				case 'r':
					opts.HostKeyPaths = append(opts.HostKeyPaths, value)
