	makeListener := func(network, address string) (net.Listener, error) {
		lc := net.ListenConfig{}
		if opts.HasInterface && opts.Interface != "" {
			ifName := opts.Interface
			// Control to set SO_BINDTODEVICE
			lc.Control = func(network, address string, c syscall.RawConn) error {
				var opErr error
				err := c.Control(func(fd uintptr) {
					opErr = setsockoptBindToDevice(int(fd), ifName)
				})
				if err != nil {
					return err
				}
				if opErr != nil {
					logMsg("Couldn't set SO_BINDTODEVICE")
					// don't fail listen
				}
				return nil
			}
