	ips, err := net.LookupIP(host)
	if err != nil {
		logMsg("Failed listening on '%s': Error resolving: Temporary failure in name resolution", spec.PortStr)
		return nil
	}
	if len(ips) == 0 {
		logMsg("Failed listening on '%s': Error resolving: Temporary failure in name resolution", spec.PortStr)
		return nil
	}
