		// does not use hostbound; treat as failure.
		sess.sendAuthFailure(false)
		return false
	}
	if !sess.userValid {
		sess.sendAuthFailure(false)
		return false
	}
	authOpts, pubkeyInfo, found := sess.checkAuthorizedKey(offered)
	if !hasSig {
		if found {
