func setCloseOnExecAll() {
	entries, err := os.ReadDir("/proc/self/fd")
	if err != nil {
		return
	}
	for _, e := range entries {
		fd, err := strconv.Atoi(e.Name())
		if err != nil || fd <= 2 {
			continue
		}
		// F_GETFD=1, F_SETFD=2, FD_CLOEXEC=1
		flags, _, errno := syscall.Syscall(syscall.SYS_FCNTL, uintptr(fd), uintptr(1), 0)
		if errno != 0 {
			continue
		}
		syscall.Syscall(syscall.SYS_FCNTL, uintptr(fd), uintptr(2), flags|1)
	}
}
