import sys
sys.path.insert(0,"/tmp")
from sshprobe import Conn, ssh_str
import struct

def parse(p):
    if not p: return "empty"
    return f"type{p[0]} len={len(p)} {p[:30]}"

def trial(port,label, payloads):
    print(f"--{port} {label}")
    try:
        c=Conn(port)
        for pl in payloads:
            c.send(pl)
            try:
                print("  ->", parse(c.recv()))
            except Exception as e:
                print("  EXC", e); break
        c.close()
    except Exception as e: print(" conn EXC", e)

def channel_open():
    w=struct.pack(">I",0)  # placeholder
    # channel open: byte90 string session uint sender uint window uint max
    return b"\x5a"+ssh_str("session")+struct.pack(">III",0,1024,32768)
def global_req():
    return b"\x50"+ssh_str("tcpip-forward")+b"\x01"+ssh_str("127.0.0.1")+struct.pack(">I",9999)
def ignore_pkt():
    return b"\x02"+ssh_str("hello ignore")
def debug_pkt():
    return b"\x04\x01"+ssh_str("debug msg")+ssh_str("")
def unknown():
    return b"\xc8\x01\x02\x03"
def disconnect_pkt():
    return b"\x01"+struct.pack(">I",11)+ssh_str("by client")+ssh_str("")

if __name__=="__main__":
    which=sys.argv[1]
    fn={"channel":lambda: trial(0,"",[channel_open()]),}
    # manual dispatch
    for port in [2321,2322]:
        if which=="channel": trial(port,"channel open pre-auth",[channel_open()])
        elif which=="global": trial(port,"global pre-auth",[global_req()])
        elif which=="ignore": trial(port,"ignore then none",[ignore_pkt(), b"\x32"+ssh_str("agent")+ssh_str("ssh-connection")+ssh_str("none")])
        elif which=="debug": trial(port,"debug then none",[debug_pkt(), b"\x32"+ssh_str("agent")+ssh_str("ssh-connection")+ssh_str("none")])
        elif which=="unknown": trial(port,"unknown 200",[unknown()])
        elif which=="disconnect": trial(port,"disconnect",[disconnect_pkt()])
        elif which=="service2": trial(port,"second service req",[b"\x05"+ssh_str("ssh-userauth")])
PY
