from postauth_probe import auth_conn
from sshprobe import ssh_str, get_str
import struct

def parse_open_resp(p):
    if not p: return "empty"
    if p[0]==91:
        off=1; rec=struct.unpack(">I",p[off:off+4])[0]; off+=4; sender=struct.unpack(">I",p[off:off+4])[0]; off+=4; win=struct.unpack(">I",p[off:off+4])[0]; off+=4; maxp=struct.unpack(">I",p[off:off+4])[0]; return f"OPEN_CONFIRM recipient={rec} sender={sender} window={win} max={maxp}"
    if p[0]==92:
        off=1; rec=struct.unpack(">I",p[off:off+4])[0]; off+=4; reason=struct.unpack(">I",p[off:off+4])[0]; off+=4; msg,off=get_str(p,off); return f"OPEN_FAIL rec={rec} reason={reason} msg={msg}"
    return f"type{p[0]} {p[:40]}"

def open_channel(c, typ, extra=b"", sender=7, window=1024, maxp=32768):
    c.send(b"\x5a"+ssh_str(typ)+struct.pack(">III",sender,window,maxp)+extra)
    return parse_open_resp(c.recv())

