package main

import (
 "bufio"
 "bytes"
 "crypto/aes"
 "crypto/cipher"
 "crypto/ecdh"
 "crypto/hmac"
 "crypto/mlkem"
 "crypto/rand"
 "crypto/sha256"
 "encoding/binary"
 "fmt"
 "math/big"
 "net"
 "os"
)

func str(b []byte) []byte { var o bytes.Buffer; binary.Write(&o,binary.BigEndian,uint32(len(b))); o.Write(b); return o.Bytes() }
func sstr(s string) []byte { return str([]byte(s)) }
func mpint(n *big.Int) []byte { if n.Sign()==0 { return str(nil) }; b:=n.Bytes(); if b[0]&0x80!=0 { b=append([]byte{0},b...) }; return str(b) }
func kAsMpint(k []byte) []byte { return mpint(new(big.Int).SetBytes(k)) }
func kAsString(k []byte) []byte { return str(k) }

type rdr struct { data []byte; pos int }
func (r *rdr) str() []byte { l:=binary.BigEndian.Uint32(r.data[r.pos:]); r.pos+=4; b:=r.data[r.pos:r.pos+int(l)]; r.pos+=int(l); return append([]byte{},b...) }

func readPlain(br *bufio.Reader) []byte {
 var lb [4]byte; if _,err:=readFull(br,lb[:]); err!=nil { panic(err) }
 plen:=binary.BigEndian.Uint32(lb[:]); body:=make([]byte,plen); if _,err:=readFull(br,body); err!=nil { panic(err) }; return body[1:int(plen)-int(body[0])]
}
func readFull(br *bufio.Reader,b []byte) (int,error){ total:=0; for total<len(b){ n,err:=br.Read(b[total:]); total+=n; if err!=nil { return total,err } }; return total,nil }
func sendPlain(conn net.Conn, payload []byte){
 pad:=8-((4+1+len(payload))%8); if pad<4 { pad+=8 }
 var o bytes.Buffer; binary.Write(&o,binary.BigEndian,uint32(1+len(payload)+pad)); o.WriteByte(byte(pad)); o.Write(payload); rb:=make([]byte,pad); rand.Read(rb); o.Write(rb); conn.Write(o.Bytes())
}

func main(){
 order:=os.Args[1]; kenc:=os.Args[2] // pqfirst or classicfirst ; mpint or string
 conn,_:=net.Dial("tcp","127.0.0.1:2321")
 br:=bufio.NewReader(conn)
