package main

import "sync"

var unauthMu sync.Mutex
var unauthCount int

const maxUnauthClients = 5

func acquireUnauth() bool {
	unauthMu.Lock()
	defer unauthMu.Unlock()
	if unauthCount >= maxUnauthClients {
		return false
	}
	unauthCount++
	return true
}

func releaseUnauth() {
	unauthMu.Lock()
	if unauthCount > 0 {
		unauthCount--
	}
	unauthMu.Unlock()
}
EOF
