import os, signal
for pid in os.listdir("/proc"):
 if pid.isdigit():
  try:
   st=open(f"/proc/{pid}/stat").read().split()[2]
   if st=='Z': continue
   cmd=open(f"/proc/{pid}/cmdline","rb").read()
   if b"executable" in cmd and int(pid)!=os.getpid():
       # avoid killing our bash (its cmdline contains script text with executable)
       if cmd.startswith(b"bash"): continue
       print(pid, cmd[:100]); os.kill(int(pid), signal.SIGTERM)
  except Exception as e: pass
PY
